export const BODY = {"level-10":{"id":"level-10","kind":"level","level":10,"src":"level:10","title":"Level 10 · The Stretch","body":"Every strand at its hardest: powers and roots, per cents and compound interest, equations, sequences and inequalities, sets, Pythagoras and trigonometry, and counting and probability, with no stabilisers.","route":"#/atlas","cta":"See the road"},"land-l10-powers":{"id":"land-l10-powers","kind":"land","level":10,"src":"land:l10-powers","title":"Powers, roots and factors — in The Square Palace","body":"4 stops on this stretch of the road: Squares and brackets · The index laws · Counting factors from the stones · Which square roots are fractions.","art":"art/w-palace.webp","route":"#/world/palace","cta":"Visit Palace"},"land-l10-decimals":{"id":"land-l10-decimals","kind":"land","level":10,"src":"land:l10-decimals","title":"Fractions, ratio and growth — in The Decimal Dock","body":"4 stops on this stretch of the road: Dividing by a fraction · Sales and rises · Ratio: simplify and share · Interest on interest.","art":"art/w-dock.webp","route":"#/world/dock","cta":"Visit Dock"},"land-l10-algebra":{"id":"land-l10-algebra","kind":"land","level":10,"src":"land:l10-algebra","title":"Equations and sequences — in Set Island","body":"5 stops on this stretch of the road: Letters for numbers · Solving equations on a balance · The nth term · Straight-line graphs · Inequalities.","art":"art/w-setisland.webp","route":"#/world/setisland","cta":"Visit Set Island"},"land-l10-sets":{"id":"land-l10-sets","kind":"land","level":10,"src":"land:l10-sets","title":"Sets and logic — in Set Island","body":"3 stops on this stretch of the road: Union and intersection · Venn diagrams that count · How many subsets?.","art":"art/w-setisland.webp","route":"#/world/setisland","cta":"Visit Set Island"},"land-l10-shape":{"id":"land-l10-shape","kind":"land","level":10,"src":"land:l10-shape","title":"Circles and triangles — in The Lighthouse","body":"6 stops on this stretch of the road: Round the circle · Pythagoras’ theorem · Tan: how tall is the tower? · Sin and cos: the ladder · The three special angles · Bearings: the way back.","art":"art/w-lighthouse.webp","route":"#/world/lighthouse","cta":"Visit Lighthouse"},"land-l10-data":{"id":"land-l10-data","kind":"land","level":10,"src":"land:l10-data","title":"Counting and chance — in The Data Carnival","body":"4 stops on this stretch of the road: Permutations: order matters · Combinations: order doesn't matter · Tree diagrams · Expected frequency.","art":"art/w-carnival.webp","route":"#/world/carnival","cta":"Visit Carnival"},"hook-divide-fractions-hook":{"id":"hook-divide-fractions-hook","kind":"hook","src":"stop:divide-fractions#hook","title":"Can you? — Dividing by a fraction","body":"3 ÷ 1/2 — how many halves fit in 3?","cta":"Find out how","level":10,"route":"#/stop/divide-fractions"},"worked-divide-fractions-worked0":{"id":"worked-divide-fractions-worked0","kind":"worked","src":"stop:divide-fractions#worked0","title":"Worked out — Dividing by a fraction: Whole ÷ a unit fraction","body":"3 ÷ 1/2: How many 1/2s fit in one whole? → 2 · In 3 wholes: 3 × 2 → 6","cta":"Watch it step by step","level":10,"route":"#/stop/divide-fractions"},"worked-divide-fractions-worked1":{"id":"worked-divide-fractions-worked1","kind":"worked","src":"stop:divide-fractions#worked1","title":"Worked out — Dividing by a fraction: Whole ÷ a bigger fraction","body":"6 ÷ 2/3: Pieces: 6 × 3 → 18 · Helpings of 2 pieces: ÷ 2 → 9","cta":"Watch it step by step","level":10,"route":"#/stop/divide-fractions"},"worked-divide-fractions-worked2":{"id":"worked-divide-fractions-worked2","kind":"worked","src":"stop:divide-fractions#worked2","title":"Worked out — Dividing by a fraction: Fraction ÷ fraction","body":"2/3 ÷ 3/4: Keep 2/3, change ÷ to ×, flip 3/4 → 4/3 · Tops: 2 × 4 → 8 · Bottoms: 3 × 3 → 9 · Top over bottom → 8/9","cta":"Watch it step by step","level":10,"route":"#/stop/divide-fractions"},"why-divide-fractions-why2":{"id":"why-divide-fractions-why2","kind":"why","src":"stop:divide-fractions#why2","title":"Why “Dividing by a fraction” works","body":"That is all \"keep, change, flip\" is: the bottom of the divisor tells you how many pieces each whole breaks into, and the top tells you how many pieces make one helping.","cta":"See why","level":10,"route":"#/stop/divide-fractions"},"moment-divide-fractions-beat3":{"id":"moment-divide-fractions-beat3","kind":"moment","src":"story:divide-fractions#beat3","badge":{"id":"story","label":"A story"},"title":"How many helpings? — on the notepad","body":"Vesper: Two thirds each. 18 ÷ 2 = 9","cta":"Read the story","level":10,"route":"#/stop/divide-fractions"},"try-divide-fractions-L10":{"id":"try-divide-fractions-L10","kind":"try","level":10,"src":"try:divide-fractions@10/3#0","title":"Dividing by a fraction — your turn","route":"#/stop/divide-fractions","cta":"Practise this stop","play":{"q":"1/2 ÷ 1/2 = ?","opts":["2/2","2/1","2"],"after":"Keep the first, change ÷ to ×, flip the second."}},"hook-interest-compound-hook":{"id":"hook-interest-compound-hook","kind":"hook","src":"stop:interest-compound#hook","title":"Can you? — Interest on interest","body":"200 coins in the story's bank at 5% a year, and each year's interest stays in. How much after 2 years?","cta":"Find out how","level":10,"route":"#/stop/interest-compound"},"worked-interest-compound-worked0":{"id":"worked-interest-compound-worked0","kind":"worked","src":"stop:interest-compound#worked0","title":"Worked out — Interest on interest: The account, year by year","body":"The story's bank pays 5% a year and each year's interest stays in the account (compound). Ines puts in 200 coins. How many coins after 2 years?: After year 1: add 5% of 200 → 210 · After year 2: add 5% of 210 → 220.5","cta":"Watch it step by step","level":10,"route":"#/stop/interest-compound"},"worked-interest-compound-worked1":{"id":"worked-interest-compound-worked1","kind":"worked","src":"stop:interest-compound#worked1","title":"Worked out — Interest on interest: Compound beats simple by…","body":"The story's bank pays 10% a year. Suki leaves 200 coins for 2 years with the interest kept in (compound). How many coins more is that than simple interest would give?: Compound: 200 → year 1 → year 2 → 242 · Simple: 200 + 2 × 10% of 200 → 240 · The difference: interest on interest → 2","cta":"Watch it step by step","level":10,"route":"#/stop/interest-compound"},"why-interest-compound-why2":{"id":"why-interest-compound-why2","kind":"why","src":"stop:interest-compound#why2","title":"Why “Interest on interest” works","body":"The numbers here always come out to whole hundredths of a coin, so nothing needs rounding. A quick way to do one year: multiply by 1.05 for 5%, 1.1 for 10% — the 1 keeps the coins you had, the rest adds the interest. The rates are the story's, not a real bank's.","cta":"See why","level":10,"route":"#/stop/interest-compound"},"moment-interest-compound-beat3":{"id":"moment-interest-compound-beat3","kind":"moment","src":"story:interest-compound#beat3","badge":{"id":"story","label":"A story"},"title":"Leave it in — on the notepad","body":"Kwame: So year two ends on… 210 + 10.5 = 220.5","cta":"Read the story","level":10,"route":"#/stop/interest-compound"},"try-interest-compound-L10":{"id":"try-interest-compound-L10","kind":"try","level":10,"src":"try:interest-compound@10/3#0","title":"Interest on interest — your turn","route":"#/stop/interest-compound","cta":"Practise this stop","play":{"q":"The story's bank pays 6% a year. Theo leaves 600 coins for 2 years with the interest kept in (compound). How many coins more is that than simple interest would give?","opts":["2.16","674.16","672"],"after":"Each year, add the interest to the account — so next year the interest is worked out on the bigger amount."}},"hook-round-the-circle-hook":{"id":"hook-round-the-circle-hook","kind":"hook","src":"stop:round-the-circle#hook","title":"Can you? — Round the circle","body":"A bicycle wheel is 60 cm across. How far does it roll in one turn?","cta":"Find out how","level":10,"route":"#/stop/round-the-circle"},"worked-round-the-circle-worked0":{"id":"worked-round-the-circle-worked0","kind":"worked","src":"stop:round-the-circle#worked0","title":"Worked out — Round the circle: Radius to diameter","body":"A circle has a radius of 6 cm. What is its diameter, in cm?: The radius → 6 · Two radii end to end → 12","cta":"Watch it step by step","level":10,"route":"#/stop/round-the-circle"},"worked-round-the-circle-worked1":{"id":"worked-round-the-circle-worked1","kind":"worked","src":"stop:round-the-circle#worked1","title":"Worked out — Round the circle: Diameter to radius","body":"A circle has a diameter of 14 cm. What is its radius, in cm?: The diameter → 14 · Half of it → 7","cta":"Watch it step by step","level":10,"route":"#/stop/round-the-circle"},"worked-round-the-circle-worked2":{"id":"worked-round-the-circle-worked2","kind":"worked","src":"stop:round-the-circle#worked2","title":"Worked out — Round the circle: Round, from the diameter","body":"A circle has a diameter of 12 cm. Using π ≈ 3.14, how far is it round the edge, in cm?: 3 × 12 → 36 · 0.14 × 12 → 1.68 · Add them → 37.68","cta":"Watch it step by step","level":10,"route":"#/stop/round-the-circle"},"worked-round-the-circle-worked3":{"id":"worked-round-the-circle-worked3","kind":"worked","src":"stop:round-the-circle#worked3","title":"Worked out — Round the circle: Round, from the radius","body":"A circle has a radius of 5 cm. Using π ≈ 3.14, how far is it round the edge, in cm?: The diameter: 2 × 5 → 10 · 3 × 10 → 30 · 0.14 × 10 → 1.4 · Add them → 31.4","cta":"Watch it step by step","level":10,"route":"#/stop/round-the-circle"},"why-round-the-circle-why2":{"id":"why-round-the-circle-why2","kind":"why","src":"stop:round-the-circle#why2","title":"Why “Round the circle” works","body":"You can see why it is a bit more than 3. Fit a hexagon inside the circle: its six sides are each one radius long, so its perimeter is 6 radii — exactly 3 diameters. The circle bulges outside the hexagon, so it must be a little longer than 3 diameters. A square drawn around the outside is 4 diameters, so π sits between 3 and 4.","cta":"See why","level":10,"route":"#/stop/round-the-circle"},"moment-round-the-circle-beat4":{"id":"moment-round-the-circle-beat4","kind":"moment","src":"story:round-the-circle#beat4","badge":{"id":"story","label":"A story"},"title":"The rolling wheel — on the notepad","body":"Vesper: Then the small part. 0.14 × 60 = 8.4","cta":"Read the story","level":10,"route":"#/stop/round-the-circle"},"try-round-the-circle-L10":{"id":"try-round-the-circle-L10","kind":"try","level":10,"src":"try:round-the-circle@10/3#0","title":"Round the circle — your turn","route":"#/stop/round-the-circle","cta":"Practise this stop","play":{"q":"A circle has a radius of 12 cm. Using π ≈ 3.14, how far is it round the edge, in cm?","opts":["75.36","24","72"],"after":"The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter."}},"hook-negative-squares-hook":{"id":"hook-negative-squares-hook","kind":"hook","src":"stop:negative-squares#hook","title":"Can you? — Squares and brackets","body":"(−3)² and −3². Are they the same number?","cta":"Find out how","level":10,"route":"#/stop/negative-squares"},"worked-negative-squares-worked0":{"id":"worked-negative-squares-worked0","kind":"worked","src":"stop:negative-squares#worked0","title":"Worked out — Squares and brackets: Square in brackets","body":"(−3)²: (−3)² is (−3) × (−3). The sizes: 3 × 3 → 9 · Two negatives multiplied make a positive, so → 9","cta":"Watch it step by step","level":10,"route":"#/stop/negative-squares"},"worked-negative-squares-worked1":{"id":"worked-negative-squares-worked1","kind":"worked","src":"stop:negative-squares#worked1","title":"Worked out — Squares and brackets: Minus, no brackets","body":"−3²: No brackets, so the power goes first: 3² → 9 · Then the minus in front → -9","cta":"Watch it step by step","level":10,"route":"#/stop/negative-squares"},"worked-negative-squares-worked2":{"id":"worked-negative-squares-worked2","kind":"worked","src":"stop:negative-squares#worked2","title":"Worked out — Squares and brackets: Square, then take away","body":"(−4)² − 5: Powers first: (−4)² → 16 · 16 − 5 → 11","cta":"Watch it step by step","level":10,"route":"#/stop/negative-squares"},"worked-negative-squares-worked3":{"id":"worked-negative-squares-worked3","kind":"worked","src":"stop:negative-squares#worked3","title":"Worked out — Squares and brackets: Times a negative","body":"10 − 4 × (−3): Multiply first: 4 × (−3) → -12 · 10 − (−12) is 10 + 12 → 22","cta":"Watch it step by step","level":10,"route":"#/stop/negative-squares"},"worked-negative-squares-worked4":{"id":"worked-negative-squares-worked4","kind":"worked","src":"stop:negative-squares#worked4","title":"Worked out — Squares and brackets: Minus square plus a product","body":"−3² + 4 × 5: Powers first: −3² (square, then the minus) → -9 · Then multiply: 4 × 5 → 20 · −9 + 20 → 11","cta":"Watch it step by step","level":10,"route":"#/stop/negative-squares"},"why-negative-squares-why2":{"id":"why-negative-squares-why2","kind":"why","src":"stop:negative-squares#why2","title":"Why “Squares and brackets” works","body":"The same order runs whole sums: powers, then × and ÷, then + and −. In 10 − 4 × (−3), multiply first: 4 × (−3) = −12. Then 10 − (−12) is 10 + 12 = 22. Take each step on its own and the signs look after themselves.","cta":"See why","level":10,"route":"#/stop/negative-squares"},"moment-negative-squares-beat3":{"id":"moment-negative-squares-beat3","kind":"moment","src":"story:negative-squares#beat3","badge":{"id":"story","label":"A story"},"title":"The calculator argument — on the notepad","body":"Theo: Without them, the power goes first. Square the 3. 3 × 3 = 9","cta":"Read the story","level":10,"route":"#/stop/negative-squares"},"try-negative-squares-L10":{"id":"try-negative-squares-L10","kind":"try","level":10,"src":"try:negative-squares@10/3#0","title":"Squares and brackets — your turn","route":"#/stop/negative-squares","cta":"Practise this stop","play":{"q":"−3² + 4 × 29 = ?","opts":["107","116","108"],"after":"Powers come before the minus sign in front — unless brackets put the minus inside the square."}},"hook-factor-count-stones-hook":{"id":"hook-factor-count-stones-hook","kind":"hook","src":"stop:factor-count-stones#hook","title":"Can you? — Counting factors from the stones","body":"2³ × 3² — how many factors does it have, without listing a single one?","cta":"Find out how","level":10,"route":"#/stop/factor-count-stones"},"worked-factor-count-stones-worked0":{"id":"worked-factor-count-stones-worked0","kind":"worked","src":"stop:factor-count-stones#worked0","title":"Worked out — Counting factors from the stones: Every stone has a power","body":"2³ × 3² — how many factors?: How many 2s can a factor take? (none, one, … up to 3) → 4 · How many 3s can a factor take? (none, one, … up to 2) → 3 · Multiply the choices: 4 × 3 → 12","cta":"Watch it step by step","level":10,"route":"#/stop/factor-count-stones"},"worked-factor-count-stones-worked1":{"id":"worked-factor-count-stones-worked1","kind":"worked","src":"stop:factor-count-stones#worked1","title":"Worked out — Counting factors from the stones: A stone on its own","body":"2² × 5 — how many factors?: How many 2s can a factor take? (none, one, … up to 2) → 3 · How many 5s can a factor take? (none, one, … up to 1) → 2 · Multiply the choices: 3 × 2 → 6","cta":"Watch it step by step","level":10,"route":"#/stop/factor-count-stones"},"why-factor-count-stones-why2":{"id":"why-factor-count-stones-why2","kind":"why","src":"stop:factor-count-stones#why2","title":"Why “Counting factors from the stones” works","body":"So the rule is: add one to each little power, and multiply. The \"add one\" is the choice of taking none of that stone — the factor 1 comes from taking none of anything. A stone written with no little number is there once, so it still gives two choices: none of it, or one.","cta":"See why","level":10,"route":"#/stop/factor-count-stones"},"moment-factor-count-stones-beat3":{"id":"moment-factor-count-stones-beat3","kind":"moment","src":"story:factor-count-stones#beat3","badge":{"id":"story","label":"A story"},"title":"Bags of biscuits — on the notepad","body":"Suki: Of the 2s it can take none, one, two or three: four choices. 3 + 1 = 4","cta":"Read the story","level":10,"route":"#/stop/factor-count-stones"},"hook-rational-roots-hook":{"id":"hook-rational-roots-hook","kind":"hook","src":"stop:rational-roots#hook","title":"Can you? — Which square roots are fractions","body":"√49 is 7. Is √50 some fraction — one whole number over another?","cta":"Find out how","level":10,"route":"#/stop/rational-roots"},"worked-rational-roots-worked0":{"id":"worked-rational-roots-worked0","kind":"worked","src":"stop:rational-roots#worked0","title":"Worked out — Which square roots are fractions: A lonely stone","body":"√50 — rational or irrational?: Write 50 in prime stones. How many different stones are left without a partner? → 1 · A lonely stone, so the root is → irrational","cta":"Watch it step by step","level":10,"route":"#/stop/rational-roots"},"worked-rational-roots-worked1":{"id":"worked-rational-roots-worked1","kind":"worked","src":"stop:rational-roots#worked1","title":"Worked out — Which square roots are fractions: Every stone paired","body":"√36 — rational or irrational?: Write 36 in prime stones. How many different stones are left without a partner? → 0 · Every stone has a partner, so the root is → rational","cta":"Watch it step by step","level":10,"route":"#/stop/rational-roots"},"worked-rational-roots-worked2":{"id":"worked-rational-roots-worked2","kind":"worked","src":"stop:rational-roots#worked2","title":"Worked out — Which square roots are fractions: A fraction, all paired","body":"√(4/9) — rational or irrational?: How many different stones of 4 are left without a partner? → 0 · And of 9? → 0 · Every stone paired, top and bottom, so it is → rational","cta":"Watch it step by step","level":10,"route":"#/stop/rational-roots"},"worked-rational-roots-worked3":{"id":"worked-rational-roots-worked3","kind":"worked","src":"stop:rational-roots#worked3","title":"Worked out — Which square roots are fractions: A fraction, one lonely","body":"√(8/9) — rational or irrational?: How many different stones of 8 are left without a partner? → 1 · And of 9? → 0 · A lonely stone somewhere, so √ of this fraction is → irrational","cta":"Watch it step by step","level":10,"route":"#/stop/rational-roots"},"why-rational-roots-why2":{"id":"why-rational-roots-why2","kind":"why","src":"stop:rational-roots#why2","title":"Why “Which square roots are fractions” works","body":"It is still a real length — the diagonal of a square with sides 5 — and 99/14 gets very close: 99 × 99 = 9801, while 50 × 14 × 14 = 9800. Close is not equal. The same argument works for fractions: in lowest terms, √(p/q) is rational only when p and q are both squares.","cta":"See why","level":10,"route":"#/stop/rational-roots"},"moment-rational-roots-beat1":{"id":"moment-rational-roots-beat1","kind":"moment","src":"story:rational-roots#beat1","badge":{"id":"story","label":"A story"},"title":"The lonely stone — on the notepad","body":"Kwame: Try 99/14. 99 × 99 is 9,801… 99 × 99 = 9801","cta":"Read the story","level":10,"route":"#/stop/rational-roots"},"try-rational-roots-L10":{"id":"try-rational-roots-L10","kind":"try","level":10,"src":"try:rational-roots@10/3#0","title":"Which square roots are fractions — your turn","route":"#/stop/rational-roots","cta":"Practise this stop","play":{"q":"√400 — rational or irrational?","opts":["rational","irrational"],"after":"Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it."}},"hook-index-laws-hook":{"id":"hook-index-laws-hook","kind":"hook","src":"stop:index-laws#hook","title":"Can you? — The index laws","body":"2³ × 2⁴ as one power of 2 — without working either out.","cta":"Find out how","level":10,"route":"#/stop/index-laws"},"worked-index-laws-worked0":{"id":"worked-index-laws-worked0","kind":"worked","src":"stop:index-laws#worked0","title":"Worked out — The index laws: Multiplying: add","body":"2³ × 2⁴ as one power of 2 — the index?: How many 2s in 2³? → 3 · And in 2⁴? → 4 · 3 + 4 → 7","cta":"Watch it step by step","level":10,"route":"#/stop/index-laws"},"worked-index-laws-worked1":{"id":"worked-index-laws-worked1","kind":"worked","src":"stop:index-laws#worked1","title":"Worked out — The index laws: Dividing: take away","body":"5⁶ ÷ 5² as one power of 5 — the index?: 5s on top → 6 · 5s underneath, to cancel → 2 · 6 − 2 → 4","cta":"Watch it step by step","level":10,"route":"#/stop/index-laws"},"worked-index-laws-worked2":{"id":"worked-index-laws-worked2","kind":"worked","src":"stop:index-laws#worked2","title":"Worked out — The index laws: Standard form","body":"34,000 = 3.4 × 10 to the power ? — the index?: How many digits in 34,000? → 5 · The point moves one fewer places → 4","cta":"Watch it step by step","level":10,"route":"#/stop/index-laws"},"worked-index-laws-worked3":{"id":"worked-index-laws-worked3","kind":"worked","src":"stop:index-laws#worked3","title":"Worked out — The index laws: Multiplying in standard form","body":"(3 × 10⁴) × (2 × 10³) = 6 × 10 to the power ? — the index?: 3 × 2 → 6 · 4 + 3 → 7 · 6 is under 10 — the index stays → 7","cta":"Watch it step by step","level":10,"route":"#/stop/index-laws"},"worked-index-laws-worked4":{"id":"worked-index-laws-worked4","kind":"worked","src":"stop:index-laws#worked4","title":"Worked out — The index laws: When the front goes past 10","body":"(4 × 10²) × (5 × 10³) = 2 × 10 to the power ? — the index?: 4 × 5 → 20 · 2 + 3 → 5 · 20 is 2 × 10 — one more power → 6","cta":"Watch it step by step","level":10,"route":"#/stop/index-laws"},"why-index-laws-why2":{"id":"why-index-laws-why2","kind":"why","src":"stop:index-laws#why2","title":"Why “The index laws” works","body":"This is exactly how scientists write huge numbers. 34,000 is 3.4 × 10,000 = 3.4 × 10⁴ — \"standard form\", one digit before the point and a power of ten. Multiply two of them and the indices add: (3 × 10⁴) × (2 × 10³) = 6 × 10⁷. If the front numbers make 10 or more, one more ten moves into the power: (4 × 10²) × (5 × 10³) = 20 × 10⁵ = 2 × 10⁶.","cta":"See why","level":10,"route":"#/stop/index-laws"},"moment-index-laws-beat3":{"id":"moment-index-laws-beat3","kind":"moment","src":"story:index-laws#beat3","badge":{"id":"story","label":"A story"},"title":"Stars over the palace — on the notepad","body":"Rafi: And ten to the four times ten to the three is seven tens multiplied — add the powers. 4 + 3 = 7","cta":"Read the story","level":10,"route":"#/stop/index-laws"},"try-index-laws-L10":{"id":"try-index-laws-L10","kind":"try","level":10,"src":"try:index-laws@10/3#0","title":"The index laws — your turn","route":"#/stop/index-laws","cta":"Practise this stop","play":{"q":"4,100 = 4.1 × 10 to the power ? — the index?","opts":["3","4","2"],"after":"Multiplying powers of the same number adds the indices; dividing subtracts them."}},"hook-percent-change-hook":{"id":"hook-percent-change-hook","kind":"hook","src":"stop:percent-change#hook","title":"Can you? — Sales and rises","body":"A 60-coin jacket has 20% off. What do you pay?","cta":"Find out how","level":10,"route":"#/stop/percent-change"},"worked-percent-change-worked0":{"id":"worked-percent-change-worked0","kind":"worked","src":"stop:percent-change#worked0","title":"Worked out — Sales and rises: Money off","body":"60 with 20% off: 20% of 60 → 12 · Take it off → 48","cta":"Watch it step by step","level":10,"route":"#/stop/percent-change"},"worked-percent-change-worked1":{"id":"worked-percent-change-worked1","kind":"worked","src":"stop:percent-change#worked1","title":"Worked out — Sales and rises: Money added","body":"80 with 15% added: 15% of 80 → 12 · Add it on → 92","cta":"Watch it step by step","level":10,"route":"#/stop/percent-change"},"worked-percent-change-worked2":{"id":"worked-percent-change-worked2","kind":"worked","src":"stop:percent-change#worked2","title":"Worked out — Sales and rises: Off, in one step","body":"120 with 35% off: Per cent you pay: 100 − 35 → 65 · 65% of 120 → 78","cta":"Watch it step by step","level":10,"route":"#/stop/percent-change"},"worked-percent-change-worked3":{"id":"worked-percent-change-worked3","kind":"worked","src":"stop:percent-change#worked3","title":"Worked out — Sales and rises: Added, in one step","body":"200 with 15% added: New per cent: 100 + 15 → 115 · 115% of 200 → 230","cta":"Watch it step by step","level":10,"route":"#/stop/percent-change"},"why-percent-change-why2":{"id":"why-percent-change-why2","kind":"why","src":"stop:percent-change#why2","title":"Why “Sales and rises” works","body":"Increases work the same way upwards: 15% more than 80 is 115% of 80, which is 92. Shops, wages and prices all move by per cents, and this is how to see where they land.","cta":"See why","level":10,"route":"#/stop/percent-change"},"moment-percent-change-beat3":{"id":"moment-percent-change-beat3","kind":"moment","src":"story:percent-change#beat3","badge":{"id":"story","label":"A story"},"title":"The jacket sale — on the notepad","body":"Dax: Twelve off. So I pay… 60 − 12 = 48","cta":"Read the story","level":10,"route":"#/stop/percent-change"},"try-percent-change-L10":{"id":"try-percent-change-L10","kind":"try","level":10,"src":"try:percent-change@10/3#0","title":"Sales and rises — your turn","route":"#/stop/percent-change","cta":"Practise this stop","play":{"q":"360 with 40% added = ?","opts":["504","140","505"],"after":"Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price)."}},"idea-ratio-share-case0":{"id":"idea-ratio-share-case0","kind":"idea","src":"stop:ratio-share#case0","title":"Ratio: simplify and share: Share in a ratio","body":"Add the parts to get one round of sharing. Find one part, then multiply by the share you want.","cta":"See it worked","level":10,"route":"#/stop/ratio-share"},"worked-ratio-share-worked1":{"id":"worked-ratio-share-worked1","kind":"worked","src":"stop:ratio-share#worked1","title":"Worked out — Ratio: simplify and share: Simplify a ratio","body":"12 : 18 in simplest form is 2 : ?: 12 ÷ what makes 2? → 6 · Same to the other side: 18 ÷ 6 → 3","cta":"Watch it step by step","level":10,"route":"#/stop/ratio-share"},"algebra-ratio-share-alg":{"id":"algebra-ratio-share-alg","kind":"algebra","src":"stop:ratio-share#alg","title":"The algebra behind “Ratio: simplify and share”","body":"n shared in a : b → n ÷ (a + b) × a and n ÷ (a + b) × b","cta":"See why","level":10,"route":"#/stop/ratio-share"},"try-ratio-share-L10":{"id":"try-ratio-share-L10","kind":"try","level":10,"src":"try:ratio-share@10/3#0","title":"Ratio: simplify and share — your turn","route":"#/stop/ratio-share","cta":"Practise this stop","play":{"q":"Share 136 in the ratio 3 : 5. How much is the smaller share?","opts":["51","8","17"],"after":"Add the parts to find how many equal shares there are. Find one share, then multiply."}},"hook-union-meet-hook":{"id":"hook-union-meet-hook","kind":"hook","src":"stop:union-meet#hook","title":"Can you? — Union and intersection","body":"A = {2, 4, 6, 8, 10}, B = {3, 6, 9}. How many in A ∪ B?","cta":"Find out how","level":10,"route":"#/stop/union-meet"},"worked-union-meet-worked0":{"id":"worked-union-meet-worked0","kind":"worked","src":"stop:union-meet#worked0","title":"Worked out — Union and intersection: Union of two lists","body":"A = {2, 4, 6, 8, 10}, B = {3, 6, 9}. n(A ∪ B)?: How many are in both A and B? → 1 · n(A) + n(B) = 5 + 3 → 8 · Take the shared ones once: − 1 → 7","cta":"Watch it step by step","level":10,"route":"#/stop/union-meet"},"worked-union-meet-worked1":{"id":"worked-union-meet-worked1","kind":"worked","src":"stop:union-meet#worked1","title":"Worked out — Union and intersection: Intersection of two lists","body":"A = {1, 3, 5, 7, 9}, B = {3, 4, 5, 6}. n(A ∩ B)?: How many are in both A and B? → 2 · So n(A ∩ B) → 2","cta":"Watch it step by step","level":10,"route":"#/stop/union-meet"},"worked-union-meet-worked2":{"id":"worked-union-meet-worked2","kind":"worked","src":"stop:union-meet#worked2","title":"Worked out — Union and intersection: Intersection by rule","body":"A = {multiples of 4 up to 50}, B = {multiples of 6 up to 50}. n(A ∩ B)?: In both means a multiple of 4 AND 6: the smallest is → 12 · How many multiples of 12 up to 50? → 4","cta":"Watch it step by step","level":10,"route":"#/stop/union-meet"},"worked-union-meet-worked3":{"id":"worked-union-meet-worked3","kind":"worked","src":"stop:union-meet#worked3","title":"Worked out — Union and intersection: Union by rule","body":"A = {multiples of 3 up to 40}, B = {multiples of 5 up to 40}. n(A ∪ B)?: In both means a multiple of 3 AND 5: the smallest is → 15 · How many multiples of 15 up to 40? → 2 · n(A) + n(B) = 13 + 8 → 21 · − 2, counted twice → 19","cta":"Watch it step by step","level":10,"route":"#/stop/union-meet"},"why-union-meet-why2":{"id":"why-union-meet-why2","kind":"why","src":"stop:union-meet#why2","title":"Why “Union and intersection” works","body":"So there is always a check: n(A ∪ B) = n(A) + n(B) − n(A ∩ B). The shared ones were counted twice by adding, so take them away once.","cta":"See why","level":10,"route":"#/stop/union-meet"},"moment-union-meet-beat3":{"id":"moment-union-meet-beat3","kind":"moment","src":"story:union-meet#beat3","badge":{"id":"story","label":"A story"},"title":"Two teams, one bus — on the notepad","body":"Dax: Oh. The overlap — A intersect B — has one child in it. I counted them twice. 1 = 1","cta":"Read the story","level":10,"route":"#/stop/union-meet"},"try-union-meet-L10":{"id":"try-union-meet-L10","kind":"try","level":10,"src":"try:union-meet@10/3#0","title":"Union and intersection — your turn","route":"#/stop/union-meet","cta":"Practise this stop","play":{"q":"A = {3, 6, 8, 10, 16, 17, 19}, B = {4, 5, 11, 16, 18, 19, 20}. n(A ∩ B)?","opts":["2","3","1"],"after":"A ∪ B (union) is everything in A or B or both; A ∩ B (intersection) is only what is in both. Count the shared ones once."}},"hook-venn-count-hook":{"id":"hook-venn-count-hook","kind":"hook","src":"stop:venn-count#hook","title":"Can you? — Venn diagrams that count","body":"14 children play cricket, 11 play chess, 5 play both. How many play at least one?","cta":"Find out how","level":10,"route":"#/stop/venn-count"},"worked-venn-count-worked0":{"id":"worked-venn-count-worked0","kind":"worked","src":"stop:venn-count#worked0","title":"Worked out — Venn diagrams that count: Add the three parts","body":"The Venn diagram shows Cricket and Chess. How many are in at least one circle?: 9 + 5 → 14 · + 6 → 20","cta":"Watch it step by step","level":10,"route":"#/stop/venn-count"},"worked-venn-count-worked1":{"id":"worked-venn-count-worked1","kind":"worked","src":"stop:venn-count#worked1","title":"Worked out — Venn diagrams that count: Add, then take the overlap","body":"14 like Cricket, 11 like Chess, 5 like both. How many like at least one?: 14 + 11 → 25 · Take the overlap once: − 5 → 20","cta":"Watch it step by step","level":10,"route":"#/stop/venn-count"},"worked-venn-count-worked2":{"id":"worked-venn-count-worked2","kind":"worked","src":"stop:venn-count#worked2","title":"Worked out — Venn diagrams that count: Find the overlap","body":"A class of 24: 14 like Cricket, 11 like Chess, 4 like neither. How many like both?: In the circles: 24 − 4 → 20 · 14 + 11 → 25 · Counted twice: 25 − 20 → 5","cta":"Watch it step by step","level":10,"route":"#/stop/venn-count"},"why-venn-count-why2":{"id":"why-venn-count-why2","kind":"why","src":"stop:venn-count#why2","title":"Why “Venn diagrams that count” works","body":"It runs backwards too. In a class of 24 where 4 play neither, 20 children are inside the circles. Adding the circles gave 25 — five too many — and the only children counted twice are the ones in the middle. So 5 play both. Whichever number is missing, the same equation finds it.","cta":"See why","level":10,"route":"#/stop/venn-count"},"moment-venn-count-beat3":{"id":"moment-venn-count-beat3","kind":"moment","src":"story:venn-count#beat3","badge":{"id":"story","label":"A story"},"title":"The club list — on the notepad","body":"Ines: Draw the circles: cricket only is 9, chess only is 6, and 5 in the middle. 14 − 5 = 9","cta":"Read the story","level":10,"route":"#/stop/venn-count"},"try-venn-count-L10":{"id":"try-venn-count-L10","kind":"try","level":10,"src":"try:venn-count@10/3#0","title":"Venn diagrams that count — your turn","route":"#/stop/venn-count","cta":"Practise this stop","play":{"q":"A class of 37: 16 like Swim, 17 like Run, 5 like neither. How many like both?","opts":["1","32","33"],"after":"Add the two circles, then take away the overlap — it was counted twice."}},"hook-substitute-hook":{"id":"hook-substitute-hook","kind":"hook","src":"stop:substitute#hook","title":"Can you? — Letters for numbers","body":"If n = 4, what is 3n + 2?","cta":"Find out how","level":10,"route":"#/stop/substitute"},"worked-substitute-worked0":{"id":"worked-substitute-worked0","kind":"worked","src":"stop:substitute#worked0","title":"Worked out — Letters for numbers: Times, then add","body":"If n = 4, what is 3n + 2?: 3 × 4 → 12 · Add 2 → 14","cta":"Watch it step by step","level":10,"route":"#/stop/substitute"},"worked-substitute-worked1":{"id":"worked-substitute-worked1","kind":"worked","src":"stop:substitute#worked1","title":"Worked out — Letters for numbers: Brackets first","body":"If n = 6, what is 4(n − 2)?: Brackets first: 6 − 2 → 4 · 4 × 4 → 16","cta":"Watch it step by step","level":10,"route":"#/stop/substitute"},"worked-substitute-worked2":{"id":"worked-substitute-worked2","kind":"worked","src":"stop:substitute#worked2","title":"Worked out — Letters for numbers: Squaring a negative","body":"If n = −3, what is 2n² + 5?: n² = −3 × −3 → 9 · 2 × 9 → 18 · Add 5 → 23","cta":"Watch it step by step","level":10,"route":"#/stop/substitute"},"worked-substitute-worked3":{"id":"worked-substitute-worked3","kind":"worked","src":"stop:substitute#worked3","title":"Worked out — Letters for numbers: Two letters","body":"If a = 4 and b = −2, what is 3a + 2b?: 3 × 4 → 12 · 2 × −2 → -4 · Add them → 8","cta":"Watch it step by step","level":10,"route":"#/stop/substitute"},"why-substitute-why2":{"id":"why-substitute-why2","kind":"why","src":"stop:substitute#why2","title":"Why “Letters for numbers” works","body":"The order still matters: multiply before you add. And a number just outside brackets multiplies everything inside: 4(n − 2) with n = 6 is 4 × 4 = 16. n² means n × n, so a negative in the box comes out positive: (−3) × (−3) = 9. And with two letters, each gets its own number.","cta":"See why","level":10,"route":"#/stop/substitute"},"moment-substitute-beat4":{"id":"moment-substitute-beat4","kind":"moment","src":"story:substitute#beat4","badge":{"id":"story","label":"A story"},"title":"The matchstick pattern — on the notepad","body":"Kwame: Then the plus 2. 12 + 2 = 14","cta":"Read the story","level":10,"route":"#/stop/substitute"},"try-substitute-L10":{"id":"try-substitute-L10","kind":"try","level":10,"src":"try:substitute@10/3#0","title":"Letters for numbers — your turn","route":"#/stop/substitute","cta":"Practise this stop","play":{"q":"If n = −9, what is 9n² + 17?","opts":["746","81","729"],"after":"A letter is a box holding a number. Put the number in the box, then do the sum — times before plus."}},"hook-subset-count-hook":{"id":"hook-subset-count-hook","kind":"hook","src":"stop:subset-count#hook","title":"Can you? — How many subsets?","body":"{a, b, c, d} — how many different smaller sets can you make from it (counting the empty one)?","cta":"Find out how","level":10,"route":"#/stop/subset-count"},"worked-subset-count-worked0":{"id":"worked-subset-count-worked0","kind":"worked","src":"stop:subset-count#worked0","title":"Worked out — How many subsets?: All the subsets","body":"How many subsets does {a, b, c, d} have?: How many members? → 4 · In or out for each: 2 × 2 × 2 × 2 → 16","cta":"Watch it step by step","level":10,"route":"#/stop/subset-count"},"worked-subset-count-worked1":{"id":"worked-subset-count-worked1","kind":"worked","src":"stop:subset-count#worked1","title":"Worked out — How many subsets?: Not empty","body":"How many subsets of {a, b, c, d} are NOT empty?: How many members? → 4 · In or out for each: 2 × 2 × 2 × 2 → 16 · Leave out the empty set → 15","cta":"Watch it step by step","level":10,"route":"#/stop/subset-count"},"worked-subset-count-worked2":{"id":"worked-subset-count-worked2","kind":"worked","src":"stop:subset-count#worked2","title":"Worked out — How many subsets?: Must contain a","body":"How many subsets of {a, b, c, d, e} contain a?: a is fixed in. How many members still to decide? → 4 · 2 choices each: 2 × 2 × 2 × 2 → 16","cta":"Watch it step by step","level":10,"route":"#/stop/subset-count"},"why-subset-count-why2":{"id":"why-subset-count-why2","kind":"why","src":"stop:subset-count#why2","title":"Why “How many subsets?” works","body":"Add one more member and every old subset splits in two — one without the new member, one with it. So each extra member doubles the count. Leave out the empty set and there are 2ⁿ − 1; insist a certain member is in and you have halved it: 2ⁿ⁻¹.","cta":"See why","level":10,"route":"#/stop/subset-count"},"moment-subset-count-beat3":{"id":"moment-subset-count-beat3","kind":"moment","src":"story:subset-count#beat3","badge":{"id":"story","label":"A story"},"title":"Toppings on the pizza — on the notepad","body":"Dax: Olives on or off, then peppers on or off… so it doubles for every topping! 2 × 2 = 4","cta":"Read the story","level":10,"route":"#/stop/subset-count"},"try-subset-count-L10":{"id":"try-subset-count-L10","kind":"try","level":10,"src":"try:subset-count@10/3#0","title":"How many subsets? — your turn","route":"#/stop/subset-count","cta":"Practise this stop","play":{"q":"How many subsets does {a, b, c, d, e, f} have?","opts":["64","6","65"],"after":"Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets."}},"hook-solve-balance-hook":{"id":"hook-solve-balance-hook","kind":"hook","src":"stop:solve-balance#hook","title":"Can you? — Solving equations on a balance","body":"3x + 4 = 19 — what is x?","cta":"Find out how","level":10,"route":"#/stop/solve-balance"},"worked-solve-balance-worked0":{"id":"worked-solve-balance-worked0","kind":"worked","src":"stop:solve-balance#worked0","title":"Worked out — Solving equations on a balance: Undo an add","body":"x + 7 = 16. What is x?: What has been added to x? → 7 · Take 7 off both sides: 16 − 7 → 9","cta":"Watch it step by step","level":10,"route":"#/stop/solve-balance"},"worked-solve-balance-worked1":{"id":"worked-solve-balance-worked1","kind":"worked","src":"stop:solve-balance#worked1","title":"Worked out — Solving equations on a balance: Undo a times","body":"4x = 24. What is x?: How many x's on the left? → 4 · Share both sides into 4: 24 ÷ 4 → 6","cta":"Watch it step by step","level":10,"route":"#/stop/solve-balance"},"worked-solve-balance-worked2":{"id":"worked-solve-balance-worked2","kind":"worked","src":"stop:solve-balance#worked2","title":"Worked out — Solving equations on a balance: Two steps","body":"3x + 4 = 19. What is x?: Take 4 off both sides → 15 · Share both sides into 3 → 5","cta":"Watch it step by step","level":10,"route":"#/stop/solve-balance"},"worked-solve-balance-worked3":{"id":"worked-solve-balance-worked3","kind":"worked","src":"stop:solve-balance#worked3","title":"Worked out — Solving equations on a balance: Words into an equation","body":"I think of a number. I multiply it by 4, then take away 3, and I get 25. What was my number?: As an equation: 4x − 3 = 25. What does 4x − 3 equal? → 25 · Add 3 to both sides → 28 · Share both sides into 4 → 7","cta":"Watch it step by step","level":10,"route":"#/stop/solve-balance"},"why-solve-balance-why2":{"id":"why-solve-balance-why2","kind":"why","src":"stop:solve-balance#why2","title":"Why “Solving equations on a balance” works","body":"The order is the building order backwards. To make 3x + 4 you multiplied by 3, then added 4; to unmake it, take the 4 away first, then divide by 3. That is also how a word puzzle becomes an equation: \"I think of a number, times it by 3 and add 4, and get 19\" IS 3x + 4 = 19.","cta":"See why","level":10,"route":"#/stop/solve-balance"},"moment-solve-balance-beat3":{"id":"moment-solve-balance-beat3","kind":"moment","src":"story:solve-balance#beat3","badge":{"id":"story","label":"A story"},"title":"The weighing scale — on the notepad","body":"Suki: Three bags balance fifteen. So share both sides into three. 15 ÷ 3 = 5","cta":"Read the story","level":10,"route":"#/stop/solve-balance"},"try-solve-balance-L10":{"id":"try-solve-balance-L10","kind":"try","level":10,"src":"try:solve-balance@10/3#0","title":"Solving equations on a balance — your turn","route":"#/stop/solve-balance","cta":"Practise this stop","play":{"q":"I think of a number. I multiply it by 9, then take away 19, and I get 107. What was my number?","opts":["14","107","126"],"after":"An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone."}},"hook-nth-term-hook":{"id":"hook-nth-term-hook","kind":"hook","src":"stop:nth-term#hook","title":"Can you? — The nth term","body":"5, 8, 11, 14, … — what is the 20th number, without writing all twenty?","cta":"Find out how","level":10,"route":"#/stop/nth-term"},"worked-nth-term-worked0":{"id":"worked-nth-term-worked0","kind":"worked","src":"stop:nth-term#worked0","title":"Worked out — The nth term: Find a far term","body":"5, 8, 11, 14, … What is the 20th term?: The step → 3 · Steps from the 1st to the 20th → 19 · 19 × 3 → 57 · + the first term, 5 → 62","cta":"Watch it step by step","level":10,"route":"#/stop/nth-term"},"worked-nth-term-worked1":{"id":"worked-nth-term-worked1","kind":"worked","src":"stop:nth-term#worked1","title":"Worked out — The nth term: The nth-term rule","body":"7, 11, 15, 19, … The nth term is 4n + □. What is □?: The step → 4 · 4n when n = 1 → 4 · First term − 4: what fixes it? → 3","cta":"Watch it step by step","level":10,"route":"#/stop/nth-term"},"worked-nth-term-worked2":{"id":"worked-nth-term-worked2","kind":"worked","src":"stop:nth-term#worked2","title":"Worked out — The nth term: Which term is it?","body":"5, 8, 11, 14, … Which term is 47?: The step → 3 · Distance from the first term: 47 − 5 → 42 · Steps: 42 ÷ 3 → 14 · Plus one for the first term → 15","cta":"Watch it step by step","level":10,"route":"#/stop/nth-term"},"why-nth-term-why2":{"id":"why-nth-term-why2","kind":"why","src":"stop:nth-term#why2","title":"Why “The nth term” works","body":"A sequence that goes up by the same amount each time is called linear, because if you plot it the points lie on a straight line. The step is the slope of that line — the next stop on this island.","cta":"See why","level":10,"route":"#/stop/nth-term"},"moment-nth-term-beat3":{"id":"moment-nth-term-beat3","kind":"moment","src":"story:nth-term#beat3","badge":{"id":"story","label":"A story"},"title":"Beach huts — on the notepad","body":"Theo: Nineteen steps of three. 19 × 3 = 57","cta":"Read the story","level":10,"route":"#/stop/nth-term"},"try-nth-term-L10":{"id":"try-nth-term-L10","kind":"try","level":10,"src":"try:nth-term@10/3#0","title":"The nth term — your turn","route":"#/stop/nth-term","cta":"Practise this stop","play":{"q":"2, 6, 10, 14, … Which term is 70?","opts":["18","4","68"],"after":"Find the step. The nth term is the step × n, plus whatever fixes the first term."}},"hook-line-graph-hook":{"id":"hook-line-graph-hook","kind":"hook","src":"stop:line-graph#hook","title":"Can you? — Straight-line graphs","body":"y = 2x + 1. When x = 3, where is the point?","cta":"Find out how","level":10,"route":"#/stop/line-graph"},"worked-line-graph-worked0":{"id":"worked-line-graph-worked0","kind":"worked","src":"stop:line-graph#worked0","title":"Worked out — Straight-line graphs: Find y from the rule","body":"y = 2x + 1. What is y when x = 3?: 2 × 3 → 6 · Add 1 → 7","cta":"Watch it step by step","level":10,"route":"#/stop/line-graph"},"worked-line-graph-worked1":{"id":"worked-line-graph-worked1","kind":"worked","src":"stop:line-graph#worked1","title":"Worked out — Straight-line graphs: Gradient from two points","body":"A straight line goes through (1, 5) and (3, 11). What is its gradient m?: The climb: 11 − 5 → 6 · The steps across: 3 − 1 → 2 · Climb ÷ steps → 3","cta":"Watch it step by step","level":10,"route":"#/stop/line-graph"},"why-line-graph-why2":{"id":"why-line-graph-why2","kind":"why","src":"stop:line-graph#why2","title":"Why “Straight-line graphs” works","body":"So from two points you can find m: how far it climbed, divided by how far it went across. From (1, 5) to (3, 11) it climbed 6 in 2 steps: m = 3. It is the nth-term step again, drawn as a picture.","cta":"See why","level":10,"route":"#/stop/line-graph"},"moment-line-graph-beat3":{"id":"moment-line-graph-beat3","kind":"moment","src":"story:line-graph#beat3","badge":{"id":"story","label":"A story"},"title":"The tide post — on the notepad","body":"Dax: And it started at 1 metre, where the line crosses the side. 6 + 1 = 7","cta":"Read the story","level":10,"route":"#/stop/line-graph"},"try-line-graph-L10":{"id":"try-line-graph-L10","kind":"try","level":10,"src":"try:line-graph@10/3#0","title":"Straight-line graphs — your turn","route":"#/stop/line-graph","cta":"Practise this stop","play":{"q":"A straight line goes through (1, 3) and (5, 7). What is its gradient m?","opts":["1","4","2"],"after":"The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis."}},"hook-pythagoras-side-hook":{"id":"hook-pythagoras-side-hook","kind":"hook","src":"stop:pythagoras-side#hook","title":"Can you? — Pythagoras’ theorem","body":"A rope runs from the top of a 12 m mast to a ring 5 m from its foot. How long is the rope — without climbing up to measure it?","cta":"Find out how","level":10,"route":"#/stop/pythagoras-side"},"worked-pythagoras-side-worked0":{"id":"worked-pythagoras-side-worked0","kind":"worked","src":"stop:pythagoras-side#worked0","title":"Worked out — Pythagoras’ theorem: Find the longest side","body":"A right-angled triangle has short sides 12 m and 5 m. How long is the longest side?: 12² → 144 · 5² → 25 · 144 + 25 → 169 · Which number squared makes 169? → 13","cta":"Watch it step by step","level":10,"route":"#/stop/pythagoras-side"},"worked-pythagoras-side-worked1":{"id":"worked-pythagoras-side-worked1","kind":"worked","src":"stop:pythagoras-side#worked1","title":"Worked out — Pythagoras’ theorem: Find a short side","body":"A right-angled triangle has a longest side of 17 m and one short side of 15 m. How long is the other short side?: 17² → 289 · 15² → 225 · 289 − 225 → 64 · Which number squared makes 64? → 8","cta":"Watch it step by step","level":10,"route":"#/stop/pythagoras-side"},"why-pythagoras-side-why2":{"id":"why-pythagoras-side-why2","kind":"why","src":"stop:pythagoras-side#why2","title":"Why “Pythagoras’ theorem” works","body":"It runs backwards too. If you know the longest side and one short side, take the small square away from the big one: 13² − 5² = 169 − 25 = 144, and 144 is 12². Sets of whole numbers that fit, like 3, 4, 5 and 5, 12, 13, are called Pythagorean triples — and any multiple of one (6, 8, 10) fits as well, because the whole triangle has just been scaled up.","cta":"See why","level":10,"route":"#/stop/pythagoras-side"},"moment-pythagoras-side-beat4":{"id":"moment-pythagoras-side-beat4","kind":"moment","src":"story:pythagoras-side#beat4","badge":{"id":"story","label":"A story"},"title":"The mast rope — on the notepad","body":"Mira: Together they make the square on the rope. 144 + 25 = 169","cta":"Read the story","level":10,"route":"#/stop/pythagoras-side"},"try-pythagoras-side-L10":{"id":"try-pythagoras-side-L10","kind":"try","level":10,"src":"try:pythagoras-side@10/3#0","title":"Pythagoras’ theorem — your turn","route":"#/stop/pythagoras-side","cta":"Practise this stop","play":{"q":"A right-angled triangle has short sides 120 m and 27 m. How long is the longest side?","opts":["123","14400","729"],"after":"In a right-angled triangle, square the two short sides and add: that is the square of the longest side."}},"hook-tan-height-hook":{"id":"hook-tan-height-hook","kind":"hook","src":"stop:tan-height#hook","title":"Can you? — Tan: how tall is the tower?","body":"A boat is 40 m from the lighthouse. The angle up to the lamp is 35°. How tall is the tower — from the boat?","cta":"Find out how","level":10,"route":"#/stop/tan-height"},"worked-tan-height-worked0":{"id":"worked-tan-height-worked0","kind":"worked","src":"stop:tan-height#worked0","title":"Worked out — Tan: how tall is the tower?: Find the height","body":"A boat is 40 m from the foot of the lighthouse. The angle up to the top is 35°. Using tan 35° ≈ 0.7, how tall is the lighthouse, in metres?: Height is opposite the angle, distance is adjacent. Which ratio links them? → tan · height = distance × tan 35° = 40 × 0.7 → 28","cta":"Watch it step by step","level":10,"route":"#/stop/tan-height"},"worked-tan-height-worked1":{"id":"worked-tan-height-worked1","kind":"worked","src":"stop:tan-height#worked1","title":"Worked out — Tan: how tall is the tower?: Find the distance","body":"The lighthouse is 25 m tall. From a boat, the angle up to the top is 27°. Using tan 27° ≈ 0.5, how far is the boat from the foot of the tower, in metres?: Height is opposite the angle, distance is adjacent. Which ratio links them? → tan · distance = height ÷ tan 27° = 25 ÷ 0.5 → 50","cta":"Watch it step by step","level":10,"route":"#/stop/tan-height"},"why-tan-height-why2":{"id":"why-tan-height-why2","kind":"why","src":"stop:tan-height#why2","title":"Why “Tan: how tall is the tower?” works","body":"So the height is 40 × 0.7 = 28 m. To go the other way — from the height back to the distance — divide instead: distance = height ÷ tan. The answer is only as good as the given ratio: tan 35° is really 0.7002…, so 28 m is right to the nearest metre.","cta":"See why","level":10,"route":"#/stop/tan-height"},"moment-tan-height-beat4":{"id":"moment-tan-height-beat4","kind":"moment","src":"story:tan-height#beat4","badge":{"id":"story","label":"A story"},"title":"Measuring the tower — on the notepad","body":"Vesper: Ours is four times as long. 4 × 7 = 28","cta":"Read the story","level":10,"route":"#/stop/tan-height"},"try-tan-height-L10":{"id":"try-tan-height-L10","kind":"try","level":10,"src":"try:tan-height@10/3#0","title":"Tan: how tall is the tower? — your turn","route":"#/stop/tan-height","cta":"Practise this stop","play":{"q":"A boat is 125 m from the foot of the lighthouse. The angle up to the top is 31°. Using tan 31° ≈ 0.6, how tall is the lighthouse, in metres?","opts":["75","76","74"],"after":"tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle."}},"hook-sin-cos-side-hook":{"id":"hook-sin-cos-side-hook","kind":"hook","src":"stop:sin-cos-side#hook","title":"Can you? — Sin and cos: the ladder","body":"A 10 m ladder leans on the lighthouse wall at 53° to the ground. How high does it reach? How far out is its foot?","cta":"Find out how","level":10,"route":"#/stop/sin-cos-side"},"worked-sin-cos-side-worked0":{"id":"worked-sin-cos-side-worked0","kind":"worked","src":"stop:sin-cos-side#worked0","title":"Worked out — Sin and cos: the ladder: Height up the wall: sin","body":"A 10 m ladder leans on the lighthouse wall, at 53° to the ground. sin 53° ≈ 0.8 and cos 53° ≈ 0.6. How high up the wall does it reach, in metres?: The ladder is the hypotenuse. The height up the wall is the side… → opposite · So the ratio to use is → sin · 10 × sin 53° = 10 × 0.8 → 8","cta":"Watch it step by step","level":10,"route":"#/stop/sin-cos-side"},"worked-sin-cos-side-worked1":{"id":"worked-sin-cos-side-worked1","kind":"worked","src":"stop:sin-cos-side#worked1","title":"Worked out — Sin and cos: the ladder: Foot from the wall: cos","body":"A 10 m ladder leans on the lighthouse wall, at 53° to the ground. sin 53° ≈ 0.8 and cos 53° ≈ 0.6. How far is its foot from the wall, in metres?: The ladder is the hypotenuse. The distance along the ground is the side… → adjacent · So the ratio to use is → cos · 10 × cos 53° = 10 × 0.6 → 6","cta":"Watch it step by step","level":10,"route":"#/stop/sin-cos-side"},"worked-sin-cos-side-worked2":{"id":"worked-sin-cos-side-worked2","kind":"worked","src":"stop:sin-cos-side#worked2","title":"Worked out — Sin and cos: the ladder: Ladder from height","body":"A ladder leans on the lighthouse wall at 30° to the ground and reaches 6 m up the wall. sin 30° = 0.5 and cos 30° ≈ 0.87. How long is the ladder, in metres?: The ladder is the hypotenuse. The height up the wall is the side… → opposite · So the ratio to use is → sin · ladder = 6 ÷ sin 30° = 6 ÷ 0.5 → 12","cta":"Watch it step by step","level":10,"route":"#/stop/sin-cos-side"},"worked-sin-cos-side-worked3":{"id":"worked-sin-cos-side-worked3","kind":"worked","src":"stop:sin-cos-side#worked3","title":"Worked out — Sin and cos: the ladder: Ladder from foot","body":"A ladder leans on the lighthouse wall at 37° to the ground, with its foot 12 m from the wall. sin 37° ≈ 0.6 and cos 37° ≈ 0.8. How long is the ladder, in metres?: The ladder is the hypotenuse. The distance along the ground is the side… → adjacent · So the ratio to use is → cos · ladder = 12 ÷ cos 37° = 12 ÷ 0.8 → 15","cta":"Watch it step by step","level":10,"route":"#/stop/sin-cos-side"},"why-sin-cos-side-why2":{"id":"why-sin-cos-side-why2","kind":"why","src":"stop:sin-cos-side#why2","title":"Why “Sin and cos: the ladder” works","body":"To remember which is which: sin goes with the opposite side, cos with the adjacent side, tan divides those two. Some people say SOH CAH TOA — Sin Opposite over Hypotenuse, Cos Adjacent over Hypotenuse, Tan Opposite over Adjacent. If you know a short side and want the ladder, divide instead: ladder = height ÷ sin.","cta":"See why","level":10,"route":"#/stop/sin-cos-side"},"moment-sin-cos-side-beat4":{"id":"moment-sin-cos-side-beat4","kind":"moment","src":"story:sin-cos-side#beat4","badge":{"id":"story","label":"A story"},"title":"The painter’s ladder — on the notepad","body":"Mira: And the foot is out by cos 53°, about 0.6 of it. 10 × 0.6 = 6","cta":"Read the story","level":10,"route":"#/stop/sin-cos-side"},"try-sin-cos-side-L10":{"id":"try-sin-cos-side-L10","kind":"try","level":10,"src":"try:sin-cos-side@10/3#0","title":"Sin and cos: the ladder — your turn","route":"#/stop/sin-cos-side","cta":"Practise this stop","play":{"q":"A 19 m ladder leans on the lighthouse wall, at 24° to the ground. sin 24° ≈ 0.4 and cos 24° ≈ 0.9. How far is its foot from the wall, in metres?","opts":["17.1","17.2","17.0"],"after":"With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos."}},"hook-special-angles-hook":{"id":"hook-special-angles-hook","kind":"hook","src":"stop:special-angles#hook","title":"Can you? — The three special angles","body":"sin x = 1/2. Which angle is x — and can you know without a calculator?","cta":"Find out how","level":10,"route":"#/stop/special-angles"},"worked-special-angles-worked0":{"id":"worked-special-angles-worked0","kind":"worked","src":"stop:special-angles#worked0","title":"Worked out — The three special angles: Sin: opposite ÷ hypotenuse","body":"sin x = 1/2, and x is between 0° and 90°. What is x?: Which triangle has sides that give 1/2: the half-square (1, 1, √2) or the half-equilateral (1, √3, 2)? → half-equilateral · In it, which angle has sin = 1/2? → 30°","cta":"Watch it step by step","level":10,"route":"#/stop/special-angles"},"why-special-angles-why2":{"id":"why-special-angles-why2","kind":"why","src":"stop:special-angles#why2","title":"Why “The three special angles” works","body":"Read the ratios off it. From the 30° corner, the side opposite is the short one, 1: sin 30° = 1/2. From the 60° corner, that same side of 1 is adjacent: cos 60° = 1/2. And tan 60° = √3 ÷ 1 = √3. Every one of these is exact, and every one is a proof you can draw on the back of an envelope.","cta":"See why","level":10,"route":"#/stop/special-angles"},"moment-special-angles-beat3":{"id":"moment-special-angles-beat3","kind":"moment","src":"story:special-angles#beat3","badge":{"id":"story","label":"A story"},"title":"The folded napkin — on the notepad","body":"Mira: tan 45° = 1, exactly. Now an equilateral triangle, side 2, cut down the middle. 2 ÷ 2 = 1","cta":"Read the story","level":10,"route":"#/stop/special-angles"},"hook-bearings-hook":{"id":"hook-bearings-hook","kind":"hook","src":"stop:bearings#hook","title":"Can you? — Bearings: the way back","body":"A ship leaves the lighthouse on a bearing of 065°. What bearing brings it straight home?","cta":"Find out how","level":10,"route":"#/stop/bearings"},"worked-bearings-worked0":{"id":"worked-bearings-worked0","kind":"worked","src":"stop:bearings#worked0","title":"Worked out — Bearings: the way back: Out under 180°: add","body":"A ship leaves the lighthouse on a bearing of 065°. What bearing takes it straight back? Type the number of degrees (a leading zero is fine either way).: Is 065° less than 180°? → Yes · So add half a turn: 65 + 180 → 245","cta":"Watch it step by step","level":10,"route":"#/stop/bearings"},"worked-bearings-worked1":{"id":"worked-bearings-worked1","kind":"worked","src":"stop:bearings#worked1","title":"Worked out — Bearings: the way back: Out over 180°: take away","body":"A ship leaves the lighthouse on a bearing of 300°. What bearing takes it straight back? Type the number of degrees (a leading zero is fine either way).: Is 300° less than 180°? → No · So take half a turn away: 300 − 180 → 120","cta":"Watch it step by step","level":10,"route":"#/stop/bearings"},"why-bearings-why2":{"id":"why-bearings-why2","kind":"why","src":"stop:bearings#why2","title":"Why “Bearings: the way back” works","body":"Check it with a picture: north and south are opposite, and so are east and west. 090° and 270° differ by 180°, and so must any bearing and its way back. The back bearing is always the other number of the pair.","cta":"See why","level":10,"route":"#/stop/bearings"},"moment-bearings-beat3":{"id":"moment-bearings-beat3","kind":"moment","src":"story:bearings#beat3","badge":{"id":"story","label":"A story"},"title":"The way home — on the notepad","body":"Theo: 065 is less than 180, so we can add half a turn without going past north. 65 + 180 = 245","cta":"Read the story","level":10,"route":"#/stop/bearings"},"hook-tree-diagram-hook":{"id":"hook-tree-diagram-hook","kind":"hook","src":"stop:tree-diagram#hook","title":"Can you? — Tree diagrams","body":"The morning ferry is late 1 time in 4, the evening ferry 2 times in 5. What is the chance both are late?","cta":"Find out how","level":10,"route":"#/stop/tree-diagram"},"worked-tree-diagram-worked0":{"id":"worked-tree-diagram-worked0","kind":"worked","src":"stop:tree-diagram#worked0","title":"Worked out — Tree diagrams: One path: multiply","body":"The chance that the morning ferry is late is 1/4. The chance that the evening ferry is late is 2/5, whatever the first one does. What is the chance that the morning ferry is late and the evening ferry is late?: The chance on the “late” branch for the morning ferry → 1/4 · The chance on the “late” branch for the evening ferry → 2/5 · Multiply along the path → 1/10","cta":"Watch it step by step","level":10,"route":"#/stop/tree-diagram"},"worked-tree-diagram-worked2":{"id":"worked-tree-diagram-worked2","kind":"worked","src":"stop:tree-diagram#worked2","title":"Worked out — Tree diagrams: Two paths: add","body":"The chance that the morning ferry is late is 1/4. The chance that the evening ferry is late is 2/5, whatever the first one does. What is the chance that exactly one of the two ferries is late?: Path late then on time: 1/4 × 3/5 → 3/20 · Path on time then late: 3/4 × 2/5 → 3/10 · Either path will do, so add them → 9/20","cta":"Watch it step by step","level":10,"route":"#/stop/tree-diagram"},"why-tree-diagram-why2":{"id":"why-tree-diagram-why2","kind":"why","src":"stop:tree-diagram#why2","title":"Why “Tree diagrams” works","body":"Why add? “Exactly one is late” can happen in two different ways — late then on time, or on time then late. Those paths never happen together, so their chances simply add. The chances on all four tips add up to 1, because between them they are everything that can happen.","cta":"See why","level":10,"route":"#/stop/tree-diagram"},"moment-tree-diagram-beat2":{"id":"moment-tree-diagram-beat2","kind":"moment","src":"story:tree-diagram#beat2","badge":{"id":"story","label":"A story"},"title":"Two ferries — on the notepad","body":"Vesper: On two fifths of those 25 days, the evening one is late too. 25 ÷ 5 × 2 = 10","cta":"Read the story","level":10,"route":"#/stop/tree-diagram"},"try-tree-diagram-L10":{"id":"try-tree-diagram-L10","kind":"try","level":10,"src":"try:tree-diagram@10/3#0","title":"Tree diagrams — your turn","route":"#/stop/tree-diagram","cta":"Practise this stop","play":{"q":"The chance that the lamp bulb fails is 3/4. The chance that the spare bulb fails is 4/5, whatever the first one does. What is the chance that the two bulbs do the same thing (both fail, or both work)?","opts":["13/20","3/5","1/20"],"after":"Multiply along the branches for one path; add the paths when more than one path counts."}},"hook-expected-frequency-hook":{"id":"hook-expected-frequency-hook","kind":"hook","src":"stop:expected-frequency#hook","title":"Can you? — Expected frequency","body":"The logbook says it rains on 3 nights in every 10. How many wet nights should the keeper plan for in the next 60?","cta":"Find out how","level":10,"route":"#/stop/expected-frequency"},"worked-expected-frequency-worked0":{"id":"worked-expected-frequency-worked0","kind":"worked","src":"stop:expected-frequency#worked0","title":"Worked out — Expected frequency: A fraction chance","body":"The keeper’s logbook shows rain on 3 nights in every 10. How many rainy nights would you expect in the next 60 nights?: The chance as a fraction: 3 out of 10, in its simplest form → 3/10 · Share the 60 trials into 10 equal parts: 60 ÷ 10 → 6 · Take 3 of those parts: 6 × 3 → 18","cta":"Watch it step by step","level":10,"route":"#/stop/expected-frequency"},"worked-expected-frequency-worked1":{"id":"worked-expected-frequency-worked1","kind":"worked","src":"stop:expected-frequency#worked1","title":"Worked out — Expected frequency: Faces of a die","body":"A fair die is rolled 60 times. How many times would you expect to roll a 5 or a 6?: The chance: winning faces out of 6, in its simplest form → 1/3 · Share the 60 trials into 3 equal parts: 60 ÷ 3 → 20","cta":"Watch it step by step","level":10,"route":"#/stop/expected-frequency"},"worked-expected-frequency-worked2":{"id":"worked-expected-frequency-worked2","kind":"worked","src":"stop:expected-frequency#worked2","title":"Worked out — Expected frequency: A decimal chance","body":"The chance of fog on any night is 0.15. How many foggy nights would you expect in 200 nights?: 0.15 as a fraction in its simplest form → 3/20 · Share the 200 trials into 20 equal parts: 200 ÷ 20 → 10 · Take 3 of those parts: 10 × 3 → 30","cta":"Watch it step by step","level":10,"route":"#/stop/expected-frequency"},"why-expected-frequency-why1":{"id":"why-expected-frequency-why1","kind":"why","src":"stop:expected-frequency#why1","title":"Why “Expected frequency” works","body":"Expected does not mean promised. Toss a coin 60 times and you expect 30 heads, but you might easily get 27, or 34 — every toss is still chancy. Real counts wobble around the expected number, sometimes above and sometimes below. What you can count on is the middle they wobble round: the more trials, the closer the share of heads creeps to 1/2, even though the count is rarely exactly half.","cta":"See why","level":10,"route":"#/stop/expected-frequency"},"algebra-expected-frequency-alg":{"id":"algebra-expected-frequency-alg","kind":"algebra","src":"stop:expected-frequency#alg","title":"The algebra behind “Expected frequency”","body":"expected frequency = P(event) × number of trials","cta":"See why","level":10,"route":"#/stop/expected-frequency"},"moral-expected-frequency-beat6":{"id":"moral-expected-frequency-beat6","kind":"moral","src":"story:expected-frequency#beat6","badge":{"id":"story","label":"A story"},"title":"Ines, in “Sixty nights of weather”","body":"Probably not exactly — maybe 15, maybe 21. Expect about 18: that is the middle the real count wobbles round, not a promise.","cta":"Read the story","level":10,"route":"#/stop/expected-frequency"},"try-expected-frequency-L10":{"id":"try-expected-frequency-L10","kind":"try","level":10,"src":"try:expected-frequency@10/3#6","title":"Expected frequency — your turn","route":"#/stop/expected-frequency","cta":"Practise this stop","play":{"q":"The chance that a passing ship signals to the lighthouse is 0.05. 220 ships pass. How many would you expect to signal?","opts":["11","1/20","12"],"after":"Expected number = probability × number of trials: take that fraction of the trials."}},"hook-inequalities-hook":{"id":"hook-inequalities-hook","kind":"hook","src":"stop:inequalities#hook","title":"Can you? — Inequalities","body":"3x + 4 < 19. Not one answer this time — a whole range of them. What is the biggest whole number that works?","cta":"Find out how","level":10,"route":"#/stop/inequalities"},"worked-inequalities-worked0":{"id":"worked-inequalities-worked0","kind":"worked","src":"stop:inequalities#worked0","title":"Worked out — Inequalities: Less than: the largest","body":"3x + 4 < 19. What is the largest integer x that makes this true?: Take 4 from both sides: 19 − 4 → 15 · Divide both sides by 3: 15 ÷ 3 → 5 · Did you divide by a negative number, so the sign turns round? → No · x < 5, so the largest integer is → 4","cta":"Watch it step by step","level":10,"route":"#/stop/inequalities"},"worked-inequalities-worked1":{"id":"worked-inequalities-worked1","kind":"worked","src":"stop:inequalities#worked1","title":"Worked out — Inequalities: More than: the smallest","body":"2x + 3 > 11. What is the smallest integer x that makes this true?: Take 3 from both sides: 11 − 3 → 8 · Divide both sides by 2: 8 ÷ 2 → 4 · Did you divide by a negative number, so the sign turns round? → No · x > 4, so the smallest integer is → 5","cta":"Watch it step by step","level":10,"route":"#/stop/inequalities"},"worked-inequalities-worked3":{"id":"worked-inequalities-worked3","kind":"worked","src":"stop:inequalities#worked3","title":"Worked out — Inequalities: The whole answer","body":"Solve 4x − 2 ≥ 10. Which of these is the answer?: Add 2 to both sides: 10 + 2 → 12 · Divide both sides by 4: 12 ÷ 4 → 3 · Did you divide by a negative number, so the sign turns round? → No · So the answer is → x ≥ 3","cta":"Watch it step by step","level":10,"route":"#/stop/inequalities"},"worked-inequalities-worked4":{"id":"worked-inequalities-worked4","kind":"worked","src":"stop:inequalities#worked4","title":"Worked out — Inequalities: Dividing by a negative","body":"−2x + 1 < 7. What is the smallest integer x that makes this true?: Take 1 from both sides: 7 − 1 → 6 · Divide both sides by −2: 6 ÷ (−2) → -3 · Did you divide by a negative number, so the sign turns round? → Yes · x > −3, so the smallest integer is → -2","cta":"Watch it step by step","level":10,"route":"#/stop/inequalities"},"why-inequalities-why2":{"id":"why-inequalities-why2","kind":"why","src":"stop:inequalities#why2","title":"Why “Inequalities” works","body":"The one trap: multiplying or dividing by a negative number flips the inequality round. On a number line, 2 < 6. Times both by −1 and you get −2 and −6 — and −2 is the higher one: −2 > −6. Multiplying by a negative mirrors the line, so the order reverses. That is why −2x < 6 means x > −3, not x < −3: try x = 0, and −2 × 0 = 0 is indeed less than 6.","cta":"See why","level":10,"route":"#/stop/inequalities"},"moment-inequalities-beat3":{"id":"moment-inequalities-beat3","kind":"moment","src":"story:inequalities#beat3","badge":{"id":"story","label":"A story"},"title":"The weight limit — on the notepad","body":"Theo: So five crates? Let me check. 3 × 5 + 4 = 19","cta":"Read the story","level":10,"route":"#/stop/inequalities"},"hook-permutations-hook":{"id":"hook-permutations-hook","kind":"hook","src":"stop:permutations#hook","title":"Can you? — Permutations: order matters","body":"8 runners in the final. How many ways can gold, silver and bronze be given out?","cta":"Find out how","level":10,"route":"#/stop/permutations"},"worked-permutations-worked0":{"id":"worked-permutations-worked0","kind":"worked","src":"stop:permutations#worked0","title":"Worked out — Permutations: order matters: Order, no repeats","body":"8 runners are in the final. How many ways can the gold, silver and bronze medals be given out?: Choices for gold → 8 · Then silver: one fewer to choose from → 7 · Then bronze: one fewer to choose from → 6 · 8 × 7 × 6 → 336","cta":"Watch it step by step","level":10,"route":"#/stop/permutations"},"worked-permutations-worked1":{"id":"worked-permutations-worked1","kind":"worked","src":"stop:permutations#worked1","title":"Worked out — Permutations: order matters: Repeats allowed","body":"A padlock has 3 dials, each showing the digits 0 to 9. How many different codes can it show?: Choices for each place — and a repeat is allowed → 10 · How many places? → 3 · 10 × 10 × 10 → 1000","cta":"Watch it step by step","level":10,"route":"#/stop/permutations"},"worked-permutations-worked2":{"id":"worked-permutations-worked2","kind":"worked","src":"stop:permutations#worked2","title":"Worked out — Permutations: order matters: The ⁿPᵣ shorthand","body":"Work out ⁷P₃: Choices for the first place → 7 · Then the second place: one fewer to choose from → 6 · Then the third place: one fewer to choose from → 5 · 7 × 6 × 5 → 210","cta":"Watch it step by step","level":10,"route":"#/stop/permutations"},"why-permutations-why2":{"id":"why-permutations-why2","kind":"why","src":"stop:permutations#why2","title":"Why “Permutations: order matters” works","body":"Watch for repeats. A padlock with 3 dials, each 0 to 9, can show 777 — so every dial keeps all 10 choices: 10 × 10 × 10 = 1,000 codes. With no repeats allowed, each place has one fewer: 10 × 9 × 8 = 720. Always ask first: can a thing be used twice?","cta":"See why","level":10,"route":"#/stop/permutations"},"moment-permutations-beat3":{"id":"moment-permutations-beat3","kind":"moment","src":"story:permutations#beat3","badge":{"id":"story","label":"A story"},"title":"The medal table — on the notepad","body":"Theo: And 6 left for bronze. 56 × 6 = 336","cta":"Read the story","level":10,"route":"#/stop/permutations"},"try-permutations-L10":{"id":"try-permutations-L10","kind":"try","level":10,"src":"try:permutations@10/3#0","title":"Permutations: order matters — your turn","route":"#/stop/permutations","cta":"Practise this stop","play":{"q":"Work out ¹¹P₃ = ?","opts":["990","11","10"],"after":"When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places."}},"hook-combinations-hook":{"id":"hook-combinations-hook","kind":"hook","src":"stop:combinations#hook","title":"Can you? — Combinations: order doesn't matter","body":"7 players, a team of 3. How many different teams — and why are there fewer than ways to give out 3 medals?","cta":"Find out how","level":10,"route":"#/stop/combinations"},"worked-combinations-worked0":{"id":"worked-combinations-worked0","kind":"worked","src":"stop:combinations#worked0","title":"Worked out — Combinations: order doesn't matter: Pairs: halve it","body":"6 friends want to enter the three-legged race. How many different pairs could they make?: In order: 6 × 5 → 30 · Each pair was counted twice — halve it → 15","cta":"Watch it step by step","level":10,"route":"#/stop/combinations"},"worked-combinations-worked1":{"id":"worked-combinations-worked1","kind":"worked","src":"stop:combinations#worked1","title":"Worked out — Combinations: order doesn't matter: A group: ÷ r!","body":"How many different teams of 3 can be picked from 7 players?: Pick 3 in order: 7 × 6 × 5 → 210 · Orders of one group of 3: 3! → 6 · 210 ÷ 6 → 35","cta":"Watch it step by step","level":10,"route":"#/stop/combinations"},"worked-combinations-worked2":{"id":"worked-combinations-worked2","kind":"worked","src":"stop:combinations#worked2","title":"Worked out — Combinations: order doesn't matter: Choose who stays out","body":"10 children want to play, but the team has 8 places. How many different teams could be picked?: Choosing 8 to play is choosing who sits out. How many sit out? → 2 · Pick 2 in order: 10 × 9 → 90 · Orders of one group of 2: 2! → 2 · 90 ÷ 2 → 45","cta":"Watch it step by step","level":10,"route":"#/stop/combinations"},"worked-combinations-worked3":{"id":"worked-combinations-worked3","kind":"worked","src":"stop:combinations#worked3","title":"Worked out — Combinations: order doesn't matter: A chance, by counting","body":"A drawer holds 4 yellow and 3 blue socks. You pull out 2 without looking. What is the chance both are yellow?: Pairs of yellow socks: 4 × 3 ÷ 2 → 6 · All the pairs: 7 × 6 ÷ 2 → 21 · The chance, as a fraction → 6/21","cta":"Watch it step by step","level":10,"route":"#/stop/combinations"},"why-combinations-why2":{"id":"why-combinations-why2","kind":"why","src":"stop:combinations#why2","title":"Why “Combinations: order doesn't matter” works","body":"Choosing who is IN also chooses who is OUT. Picking 8 of 10 for a team is the same as picking the 2 to leave out, so ¹⁰C₈ = ¹⁰C₂ = 10 × 9 ÷ 2 = 45. Count the smaller side. And a chance can be counted this way too: the pairs you want, out of all the pairs.","cta":"See why","level":10,"route":"#/stop/combinations"},"moment-combinations-beat3":{"id":"moment-combinations-beat3","kind":"moment","src":"story:combinations#beat3","badge":{"id":"story","label":"A story"},"title":"Picking the quiz team — on the notepad","body":"Nova: Oh. Asha, Ben and Chen is the same team as Chen, Ben and Asha. How many orders does one team have? 3 × 2 × 1 = 6","cta":"Read the story","level":10,"route":"#/stop/combinations"},"try-combinations-L10":{"id":"try-combinations-L10","kind":"try","level":10,"src":"try:combinations@10/3#0","title":"Combinations: order doesn't matter — your turn","route":"#/stop/combinations","cta":"Practise this stop","play":{"q":"How many different teams of 3 can be picked from 7 players?","opts":["35","210","6"],"after":"Count as if order mattered, then divide by r! — the number of orders each group was counted in."}},"word-algebra":{"id":"word-algebra","kind":"word","src":"dictionary:algebra#def","title":"algebra","body":"Maths that uses letters to stand for numbers, so one rule can cover every case. For example: 2 + 9 = 9 + 2, and a + b = b + a for every a and b.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-algebra":{"id":"wordq-algebra","kind":"wordq","src":"dictionary:algebra#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2 + 9 = 9 + 2, and a + b = b + a for every a and b.”","opts":["algebra","direct proportion","coordinates"],"after":"algebra: Maths that uses letters to stand for numbers, so one rule can cover every case."},"level":10},"word-circle":{"id":"word-circle","kind":"word","src":"dictionary:circle#def","title":"circle","body":"A round flat shape where every point on the edge is the same distance from the centre. For example: Radius 3 cm: area about 3.14 × 3 × 3 = 28.26 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-circle":{"id":"wordq-circle","kind":"wordq","src":"dictionary:circle#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Radius 3 cm: area about 3.14 × 3 × 3 = 28.26 cm².”","opts":["circle","like terms","speed"],"after":"circle: A round flat shape where every point on the edge is the same distance from the centre."},"level":10},"word-circumference":{"id":"word-circumference","kind":"word","src":"dictionary:circumference#def","title":"circumference","body":"The distance all the way round a circle. For example: About 3.14 times the width: a 10 cm wheel is about 31.4 cm round.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-circumference":{"id":"wordq-circumference","kind":"wordq","src":"dictionary:circumference#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “About 3.14 times the width: a 10 cm wheel is about 31.4 cm round.”","opts":["circumference","half","equation"],"after":"circumference: The distance all the way round a circle."},"level":10},"word-combination":{"id":"word-combination","kind":"word","src":"dictionary:combination#def","title":"combination","body":"A choice of things where the order does not count, so ABC and CBA are the same group. From n things, r of them: n! ÷ (r! × (n − r)!). For example: A team of 3 from 7 players: 7 × 6 × 5 ÷ 6 = 35.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-combination":{"id":"wordq-combination","kind":"wordq","src":"dictionary:combination#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A team of 3 from 7 players: 7 × 6 × 5 ÷ 6 = 35.”","opts":["combination","triangular number","cuboid"],"after":"combination: A choice of things where the order does not count, so ABC and CBA are the same group. From n things, r of them: n! ÷ (r! × (n − r)!)."},"level":10},"word-diameter":{"id":"word-diameter","kind":"word","src":"dictionary:diameter#def","title":"diameter","body":"The distance straight across a circle through its centre — two radii end to end. For example: Radius 4 cm → 8 cm across.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-diameter":{"id":"wordq-diameter","kind":"wordq","src":"dictionary:diameter#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Radius 4 cm → 8 cm across.”","opts":["diameter","even","unlikely"],"after":"diameter: The distance straight across a circle through its centre — two radii end to end."},"level":10},"word-discount":{"id":"word-discount","kind":"word","src":"dictionary:discount#def","title":"discount","body":"An amount taken off a price. For example: 20% off £40 saves £8, so you pay £32.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-discount":{"id":"wordq-discount","kind":"wordq","src":"dictionary:discount#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “20% off £40 saves £8, so you pay £32.”","opts":["discount","volume","numerator"],"after":"discount: An amount taken off a price."},"level":10},"word-equation":{"id":"word-equation","kind":"word","src":"dictionary:equation#def","title":"equation","body":"A statement that two things are equal, with an = sign between them. For example: 2x + 1 = 9.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-equation":{"id":"wordq-equation","kind":"wordq","src":"dictionary:equation#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2x + 1 = 9.”","opts":["equation","quotient","perpendicular height"],"after":"equation: A statement that two things are equal, with an = sign between them."},"level":10},"word-expression":{"id":"word-expression","kind":"word","src":"dictionary:expression#def","title":"expression","body":"Numbers and letters joined by operations, with no equals sign. For example: 3x + 2 (while 3x + 2 = 11 is an equation).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-expression":{"id":"wordq-expression","kind":"wordq","src":"dictionary:expression#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3x + 2 (while 3x + 2 = 11 is an equation).”","opts":["expression","line of symmetry","hexagon"],"after":"expression: Numbers and letters joined by operations, with no equals sign."},"level":10},"word-formula":{"id":"word-formula","kind":"word","src":"dictionary:formula#def","title":"formula","body":"A rule written with letters that links quantities together. For example: A = l × w: a 5 by 3 rectangle has A = 15.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-formula":{"id":"wordq-formula","kind":"wordq","src":"dictionary:formula#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A = l × w: a 5 by 3 rectangle has A = 15.”","opts":["formula","brackets","vertically opposite angles"],"after":"formula: A rule written with letters that links quantities together."},"level":10},"word-gradient":{"id":"word-gradient","kind":"word","src":"dictionary:gradient#def","title":"gradient","body":"How steep a line is: how far it rises for each one step across. For example: y = 3x + 1 rises 3 for every 1 across.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-gradient":{"id":"wordq-gradient","kind":"wordq","src":"dictionary:gradient#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “y = 3x + 1 rises 3 for every 1 across.”","opts":["gradient","cuboid","chance"],"after":"gradient: How steep a line is: how far it rises for each one step across."},"level":10},"word-index-laws":{"id":"word-index-laws","kind":"word","src":"dictionary:index laws#def","title":"index laws","body":"Rules for powers of the same number: add the little raised numbers when you multiply, take them away when you divide. For example: 2³ × 2⁴ = 2⁷ = 128.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-index-laws":{"id":"wordq-index-laws","kind":"wordq","src":"dictionary:index laws#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2³ × 2⁴ = 2⁷ = 128.”","opts":["index laws","universal set","reciprocal"],"after":"index laws: Rules for powers of the same number: add the little raised numbers when you multiply, take them away when you divide."},"level":10},"word-intercept":{"id":"word-intercept","kind":"word","src":"dictionary:intercept#def","title":"intercept","body":"Where a line crosses the y-axis — the one that runs up and down. For example: y = 2x + 5 crosses it at (0, 5).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-intercept":{"id":"wordq-intercept","kind":"wordq","src":"dictionary:intercept#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “y = 2x + 5 crosses it at (0, 5).”","opts":["intercept","regular","sample space"],"after":"intercept: Where a line crosses the y-axis — the one that runs up and down."},"level":10},"word-intersection":{"id":"word-intersection","kind":"word","src":"dictionary:intersection#def","title":"intersection","body":"Only the things that are in both sets at once. Sign: ∩. For example: {1, 2} ∩ {2, 3} = {2}.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"word-linear":{"id":"word-linear","kind":"word","src":"dictionary:linear#def","title":"linear","body":"Making a straight line when you draw it, with no letter squared or higher. For example: y = 2x + 1.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"word-nth-term":{"id":"word-nth-term","kind":"word","src":"dictionary:nth term#def","title":"nth term","body":"A rule that gives any number in a sequence straight from its position, n. For example: 4n − 1 gives 3, 7, 11, 15, …; the 10th is 39.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-nth-term":{"id":"wordq-nth-term","kind":"wordq","src":"dictionary:nth term#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “4n − 1 gives 3, 7, 11, 15, …; the 10th is 39.”","opts":["nth term","multiplication","kilometre"],"after":"nth term: A rule that gives any number in a sequence straight from its position, n."},"level":10},"word-percentage-change":{"id":"word-percentage-change","kind":"word","src":"dictionary:percentage change#def","title":"percentage change","body":"How much something went up or down, as a part of what it started at, times 100. For example: From 50 to 60: a rise of 10, and 10 ÷ 50 × 100 = 20%.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-percentage-change":{"id":"wordq-percentage-change","kind":"wordq","src":"dictionary:percentage change#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “From 50 to 60: a rise of 10, and 10 ÷ 50 × 100 = 20%.”","opts":["percentage change","scale factor","decimal point"],"after":"percentage change: How much something went up or down, as a part of what it started at, times 100."},"level":10},"word-permutation":{"id":"word-permutation","kind":"word","src":"dictionary:permutation#def","title":"permutation","body":"A choice of things where the order counts, so ABC and CBA are different. From n things, r in order: n! ÷ (n − r)!. For example: Gold, silver and bronze from 8 runners: 8 × 7 × 6 = 336.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-permutation":{"id":"wordq-permutation","kind":"wordq","src":"dictionary:permutation#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Gold, silver and bronze from 8 runners: 8 × 7 × 6 = 336.”","opts":["permutation","angles round a point","term-to-term rule"],"after":"permutation: A choice of things where the order counts, so ABC and CBA are different. From n things, r in order: n! ÷ (n − r)!."},"level":10},"word-pi":{"id":"word-pi","kind":"word","src":"dictionary:pi#def","title":"pi","body":"The number you get by dividing any circle’s distance round by its distance across — about 3.14. Sign: π. For example: C = π × d: 10 cm across gives about 31.4 cm round.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"word-proportion":{"id":"word-proportion","kind":"word","src":"dictionary:proportion#def","title":"proportion","body":"A part compared with the whole — or two amounts that grow and shrink together at the same rate. For example: 3 sweets out of 12 is a quarter.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-proportion":{"id":"wordq-proportion","kind":"wordq","src":"dictionary:proportion#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3 sweets out of 12 is a quarter.”","opts":["proportion","set","diagonal"],"after":"proportion: A part compared with the whole — or two amounts that grow and shrink together at the same rate."},"level":10},"word-radius":{"id":"word-radius","kind":"word","src":"dictionary:radius#def","title":"radius","body":"The distance from the centre of a circle out to its edge. Plural: radii. For example: A circle 10 cm across has one of 5 cm.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-radius":{"id":"wordq-radius","kind":"wordq","src":"dictionary:radius#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A circle 10 cm across has one of 5 cm.”","opts":["radius","arrangement","function machine"],"after":"radius: The distance from the centre of a circle out to its edge. Plural: radii."},"level":10},"word-ratio":{"id":"word-ratio","kind":"word","src":"dictionary:ratio#def","title":"ratio","body":"A way of comparing amounts, written with a colon, like 2 : 3. For example: Red to blue 2 : 3 means 2 red for every 3 blue.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-ratio":{"id":"wordq-ratio","kind":"wordq","src":"dictionary:ratio#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Red to blue 2 : 3 means 2 red for every 3 blue.”","opts":["ratio","factorise","less than"],"after":"ratio: A way of comparing amounts, written with a colon, like 2 : 3."},"level":10},"word-reciprocal":{"id":"word-reciprocal","kind":"word","src":"dictionary:reciprocal#def","title":"reciprocal","body":"1 divided by a number — for a fraction, the fraction turned upside down. For example: For 3/4 it is 4/3, and 3/4 × 4/3 = 1.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-reciprocal":{"id":"wordq-reciprocal","kind":"wordq","src":"dictionary:reciprocal#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “For 3/4 it is 4/3, and 3/4 × 4/3 = 1.”","opts":["reciprocal","protractor","whole number"],"after":"reciprocal: 1 divided by a number — for a fraction, the fraction turned upside down."},"level":10},"word-scale":{"id":"word-scale","kind":"word","src":"dictionary:scale#def","title":"scale","body":"A ratio that tells you how lengths on a map or drawing compare with the real ones. For example: 1 : 100 means 1 cm on paper is 1 m for real.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-scale":{"id":"wordq-scale","kind":"wordq","src":"dictionary:scale#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “1 : 100 means 1 cm on paper is 1 m for real.”","opts":["scale","prime number","simplify"],"after":"scale: A ratio that tells you how lengths on a map or drawing compare with the real ones."},"level":10},"word-sector":{"id":"word-sector","kind":"word","src":"dictionary:sector#def","title":"sector","body":"A slice of a circle between two radii, like a slice of pie. For example: A quarter-circle has a 90° angle at the centre.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-sector":{"id":"wordq-sector","kind":"wordq","src":"dictionary:sector#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A quarter-circle has a 90° angle at the centre.”","opts":["sector","volume","change"],"after":"sector: A slice of a circle between two radii, like a slice of pie."},"level":10},"word-sequence":{"id":"word-sequence","kind":"word","src":"dictionary:sequence#def","title":"sequence","body":"A list of numbers that follows a rule. For example: 3, 7, 11, 15, … goes up in 4s.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-sequence":{"id":"wordq-sequence","kind":"wordq","src":"dictionary:sequence#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3, 7, 11, 15, … goes up in 4s.”","opts":["sequence","outlier","nikhilam"],"after":"sequence: A list of numbers that follows a rule."},"level":10},"word-share-in-a-ratio":{"id":"word-share-in-a-ratio","kind":"word","src":"dictionary:share in a ratio#def","title":"share in a ratio","body":"Split an amount into unequal parts: add the parts of the ratio, find what one part is worth, then multiply. For example: £20 in 2 : 3 → 5 parts of £4 → £8 and £12.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-share-in-a-ratio":{"id":"wordq-share-in-a-ratio","kind":"wordq","src":"dictionary:share in a ratio#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “£20 in 2 : 3 → 5 parts of £4 → £8 and £12.”","opts":["share in a ratio","factor pair","rectangle"],"after":"share in a ratio: Split an amount into unequal parts: add the parts of the ratio, find what one part is worth, then multiply."},"level":10},"word-solve":{"id":"word-solve","kind":"word","src":"dictionary:solve#def","title":"solve","body":"Find the value that makes an equation true. For example: 2x + 1 = 9 → 2x = 8 → x = 4.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-solve":{"id":"wordq-solve","kind":"wordq","src":"dictionary:solve#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2x + 1 = 9 → 2x = 8 → x = 4.”","opts":["solve","analogue clock","vertex"],"after":"solve: Find the value that makes an equation true."},"level":10},"word-subset":{"id":"word-subset","kind":"word","src":"dictionary:subset#def","title":"subset","body":"A set made only from things that are in another set. For example: {1, 2} is one of {1, 2, 3}.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"word-substitute":{"id":"word-substitute","kind":"word","src":"dictionary:substitute#def","title":"substitute","body":"Put a number in place of a letter. For example: If a = 3, then 4a + 1 = 4 × 3 + 1 = 13.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-substitute":{"id":"wordq-substitute","kind":"wordq","src":"dictionary:substitute#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “If a = 3, then 4a + 1 = 4 × 3 + 1 = 13.”","opts":["substitute","greater than","empty set"],"after":"substitute: Put a number in place of a letter."},"level":10},"word-term":{"id":"word-term","kind":"word","src":"dictionary:term#def","title":"term","body":"One number in a sequence, or one part of an expression between the + and − signs. For example: 3x + 5y − 2 has three.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-term":{"id":"wordq-term","kind":"wordq","src":"dictionary:term#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3x + 5y − 2 has three.”","opts":["term","parallelogram","metric"],"after":"term: One number in a sequence, or one part of an expression between the + and − signs."},"level":10},"word-term-to-term-rule":{"id":"word-term-to-term-rule","kind":"word","src":"dictionary:term-to-term rule#def","title":"term-to-term rule","body":"How to get from each number in a sequence to the next one. For example: “Add 4” takes 3, 7, 11 on to 15.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-term-to-term-rule":{"id":"wordq-term-to-term-rule","kind":"wordq","src":"dictionary:term-to-term rule#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? ““Add 4” takes 3, 7, 11 on to 15.”","opts":["term-to-term rule","rate","scalene triangle"],"after":"term-to-term rule: How to get from each number in a sequence to the next one."},"level":10},"word-union":{"id":"word-union","kind":"word","src":"dictionary:union#def","title":"union","body":"Everything that is in either set, or in both. Sign: ∪. For example: {1, 2} ∪ {2, 3} = {1, 2, 3}.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"word-universal-set":{"id":"word-universal-set","kind":"word","src":"dictionary:universal set#def","title":"universal set","body":"Everything being talked about — the box drawn round a Venn diagram. For example: Sorting 1 to 10, it is {1, 2, …, 10}.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-universal-set":{"id":"wordq-universal-set","kind":"wordq","src":"dictionary:universal set#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Sorting 1 to 10, it is {1, 2, …, 10}.”","opts":["universal set","sum","number bond"],"after":"universal set: Everything being talked about — the box drawn round a Venn diagram."},"level":10},"word-unknown":{"id":"word-unknown","kind":"word","src":"dictionary:unknown#def","title":"unknown","body":"A letter standing for one number you are trying to find. For example: In x + 4 = 11, x is 7.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-unknown":{"id":"wordq-unknown","kind":"wordq","src":"dictionary:unknown#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In x + 4 = 11, x is 7.”","opts":["unknown","decimal place","clockwise"],"after":"unknown: A letter standing for one number you are trying to find."},"level":10},"word-variable":{"id":"word-variable","kind":"word","src":"dictionary:variable#def","title":"variable","body":"A letter that stands for a number which can change. For example: In y = 2x + 1, x and y can both take many values.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-variable":{"id":"wordq-variable","kind":"wordq","src":"dictionary:variable#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In y = 2x + 1, x and y can both take many values.”","opts":["variable","cuboid","chance"],"after":"variable: A letter that stands for a number which can change."},"level":10},"word-venn-diagram":{"id":"word-venn-diagram","kind":"word","src":"dictionary:Venn diagram#def","title":"Venn diagram","body":"Overlapping circles that sort things into groups; the overlap holds what belongs to both. For example: 5 have only a cat, 4 only a dog, 3 have both.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":10},"wordq-venn-diagram":{"id":"wordq-venn-diagram","kind":"wordq","src":"dictionary:Venn diagram#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “5 have only a cat, 4 only a dog, 3 have both.”","opts":["Venn diagram","vertically opposite angles","even"],"after":"Venn diagram: Overlapping circles that sort things into groups; the overlap holds what belongs to both."},"level":10},"formula-circumference":{"id":"formula-circumference","kind":"formula","src":"formula:circumference","title":"Circumference of a circle","body":"C = π × d = 2 × π × r. Unroll any circle: it is just over three diameters long.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Circumference of a circle: A circle 10 cm across (use π = 3.14).","opts":["31.4","31.5","31.3"],"after":"C = 3.14 × 10 · = 31.4 cm"},"level":10},"formula-why-circumference-0":{"id":"formula-why-circumference-0","kind":"formula-why","src":"formula:circumference#why0","title":"Why C = π × d = 2 × π × r","body":"Every circle, big or small, is the same shape — only its size changes. So the distance round it is always the same number of times the distance across.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-circumference-1":{"id":"formula-why-circumference-1","kind":"formula-why","src":"formula:circumference#why1","title":"Why C = π × d = 2 × π × r","body":"That number is π, a little more than 3: about 3.14. Wrap a string round a tin and it goes just over three times its width. So C = π × d — or 2 × π × r, because the diameter is two radii.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-circumference":{"id":"formula-story-circumference","kind":"formula-story","src":"formula:circumference#story","badge":{"id":"story","label":"A story"},"title":"The bicycle wheel","body":"Pip’s bike wheel is 60 cm across. How far does the bike roll in one turn of the wheel? — with Theo and Pip.","art":"art/s-city.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-circumference":{"id":"formula-try-circumference","kind":"formula-try","src":"formula:circumference#gen0","title":"Circumference of a circle — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Distance round a circle 20 cm across (use π = 3.14; in cm) = ?","opts":["62.8","62.9","62.7"],"after":"C = π × d = 2 × π × r"},"level":10},"formula-area-circle":{"id":"formula-area-circle","kind":"formula","src":"formula:area-circle","title":"Area of a circle","body":"A = π × r². Slices laid top-to-tail make a near-rectangle, r tall and π × r long.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a circle: A circle with radius 5 cm (use π = 3.14).","opts":["78.5","78.6","78.4"],"after":"r² = 5 × 5 = 25 · A = 3.14 × 25 = 78.5 cm²"},"level":10},"formula-why-area-circle-0":{"id":"formula-why-area-circle-0","kind":"formula-why","src":"formula:area-circle#why0","title":"Why A = π × r²","body":"Cut a circle into many thin slices, like a pizza, and lay them in a row, pointing up and down in turn. They make a shape that is nearly a rectangle — and the thinner the slices, the straighter it gets.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-area-circle-1":{"id":"formula-why-area-circle-1","kind":"formula-why","src":"formula:area-circle#why1","title":"Why A = π × r²","body":"Its height is the radius r. Its length is half the way round the circle, π × r. So the area is π × r × r, written π r².","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-area-circle":{"id":"formula-story-area-circle","kind":"formula-story","src":"formula:area-circle#story","badge":{"id":"story","label":"A story"},"title":"The round pond","body":"The park pond is a circle with a radius of 10 metres. Rafi wants its area for a school project. — with Mira and Rafi.","art":"art/s-pond.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-area-circle":{"id":"formula-try-area-circle","kind":"formula-try","src":"formula:area-circle#gen0","title":"Area of a circle — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a circle with radius 3 cm (use π = 3.14; in cm²) = ?","opts":["28.26","28.27","28.25"],"after":"A = π × r²"},"level":10},"formula-volume-cylinder":{"id":"formula-volume-cylinder","kind":"formula","src":"formula:volume-cylinder","title":"Volume of a cylinder","body":"V = π × r² × h. A circle, stacked up to height h.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Volume of a cylinder: A tin with radius 5 cm and height 10 cm (use π = 3.14).","opts":["785","786","784"],"after":"end: 3.14 × 5 × 5 = 78.5 cm² · V = 78.5 × 10 = 785 cm³"},"level":10},"formula-why-volume-cylinder-0":{"id":"formula-why-volume-cylinder-0","kind":"formula-why","src":"formula:volume-cylinder#why0","title":"Why V = π × r² × h","body":"A cylinder is a prism with a circle at each end, so the prism rule still works: area of the end × length.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-volume-cylinder-1":{"id":"formula-why-volume-cylinder-1","kind":"formula-why","src":"formula:volume-cylinder#why1","title":"Why V = π × r² × h","body":"The end is a circle with area π × r², so V = π × r² × h. A tin twice as tall holds twice as much; a tin twice as wide holds four times as much, because the radius is squared.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-volume-cylinder":{"id":"formula-story-volume-cylinder","kind":"formula-story","src":"formula:volume-cylinder#story","badge":{"id":"story","label":"A story"},"title":"The water tank","body":"A round water tank in the garden has a radius of 1 metre and stands 2 metres tall. — with Kwame and Nova.","art":"art/s-garden.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-volume-cylinder":{"id":"formula-try-volume-cylinder","kind":"formula-try","src":"formula:volume-cylinder#gen0","title":"Volume of a cylinder — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Volume of a cylinder, radius 2 cm and height 18 cm (use π = 3.14; in cm³) = ?","opts":["226.08","226.09","226.07"],"after":"V = π × r² × h"},"level":10},"formula-index-multiply":{"id":"formula-index-multiply","kind":"formula","src":"formula:index-multiply","title":"Multiplying powers","body":"aᵐ × aⁿ = aᵐ⁺ⁿ. Three 2s and two more 2s make a row of five 2s.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Multiplying powers: 2³ × 2⁴.","opts":["128","129","127"],"after":"3 + 4 = 7, so 2⁷ · 2⁷ = 128"},"level":10},"formula-why-index-multiply-0":{"id":"formula-why-index-multiply-0","kind":"formula-why","src":"formula:index-multiply#why0","title":"Why aᵐ × aⁿ = aᵐ⁺ⁿ","body":"2³ means three 2s multiplied together, and 2² means two more. Multiply them and you just have a longer row of 2s: 2 × 2 × 2 × 2 × 2.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-index-multiply-1":{"id":"formula-why-index-multiply-1","kind":"formula-why","src":"formula:index-multiply#why1","title":"Why aᵐ × aⁿ = aᵐ⁺ⁿ","body":"Count the 2s: 3 + 2 = 5. So when the base is the same, multiplying powers adds the little numbers, and dividing takes them away: 2⁵ ÷ 2² = 2³, because two of the 2s cancel.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-index-multiply":{"id":"formula-story-index-multiply","kind":"formula-story","src":"formula:index-multiply#story","badge":{"id":"story","label":"A story"},"title":"The folded paper","body":"Theo folds a sheet of paper in half 3 times. Kwame takes it and folds it in half 2 more times. How many layers thick is it now? — with Kwame and Theo.","art":"art/s-library.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-index-multiply":{"id":"formula-try-index-multiply","kind":"formula-try","src":"formula:index-multiply#gen0","title":"Multiplying powers — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"3¹ × 3³ is 3 to the power of what?","opts":["4","5","3"],"after":"aᵐ × aⁿ = aᵐ⁺ⁿ"},"level":10},"formula-index-power":{"id":"formula-index-power","kind":"formula","src":"formula:index-power","title":"A power of a power","body":"(aᵐ)ⁿ = aᵐˣⁿ. Two copies of three 2s: six 2s.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A power of a power: (3²)³.","opts":["729","730","728"],"after":"2 × 3 = 6, so 3⁶ · 3⁶ = 729"},"level":10},"formula-why-index-power-0":{"id":"formula-why-index-power-0","kind":"formula-why","src":"formula:index-power#why0","title":"Why (aᵐ)ⁿ = aᵐˣⁿ","body":"(2³)² means 2³ written down twice and multiplied: (2 × 2 × 2) × (2 × 2 × 2).","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-index-power-1":{"id":"formula-why-index-power-1","kind":"formula-why","src":"formula:index-power#why1","title":"Why (aᵐ)ⁿ = aᵐˣⁿ","body":"That is 2 copies of 3 twos — 6 twos in all. So a power of a power multiplies the little numbers: (aᵐ)ⁿ = aᵐˣⁿ. And a⁰ = 1, because dividing aᵐ by itself takes all m away and leaves 1.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-index-power":{"id":"formula-story-index-power","kind":"formula-story","src":"formula:index-power#story","badge":{"id":"story","label":"A story"},"title":"The bakery trolley","body":"At the bakery a tray holds cakes in a square, 3 by 3. A trolley holds trays in a square too, 3 by 3. How many cakes on a full trolley? — with Rafi and Vesper.","art":"art/s-bakery.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-index-power":{"id":"formula-try-index-power","kind":"formula-try","src":"formula:index-power#gen0","title":"A power of a power — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"(3²)³ is 3 to the power of what?","opts":["6","7","5"],"after":"(aᵐ)ⁿ = aᵐˣⁿ"},"level":10},"formula-nth-term":{"id":"formula-nth-term","kind":"formula","src":"formula:nth-term","title":"The nth term","body":"Tₙ = a + (n − 1) × d. Each step adds d; the nth term is n − 1 steps from the first.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"The nth term: The 20th term of 5, 8, 11, 14, …","opts":["62","63","61"],"after":"19 steps of 3 = 57 · 5 + 57 = 62"},"level":10},"formula-why-nth-term-1":{"id":"formula-why-nth-term-1","kind":"formula-why","src":"formula:nth-term#why1","title":"Why Tₙ = a + (n − 1) × d","body":"So the nth term is a + (n − 1) × d. Tidied up, it is d × n + (a − d): for 5, 8, 11, 14, … that is 3n + 2. The number in front of n is always the step.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-nth-term":{"id":"formula-try-nth-term","kind":"formula-try","src":"formula:nth-term#gen0","title":"The nth term — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"6, 14, 22, 30, … What is term number 23?","opts":["182","183","181"],"after":"Tₙ = a + (n − 1) × d"},"level":10},"formula-why-pythagoras-0":{"id":"formula-why-pythagoras-0","kind":"formula-why","src":"formula:pythagoras#why0","title":"Why a² + b² = c²","body":"This card is for 13- and 14-year-olds. In a right-angled triangle, build a square on each side. The two squares on the shorter sides, a² and b², together have exactly the area of the square on the longest side, c².","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-pythagoras":{"id":"formula-story-pythagoras","kind":"formula-story","src":"formula:pythagoras#story","badge":{"id":"story","label":"A story"},"title":"The shortcut across the park","body":"Dax walks 30 m along one edge of a rectangular park, then 40 m up the side. Vesper cuts straight across the grass. How much shorter is her path? — with Vesper and Dax.","art":"art/s-city.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-subsets":{"id":"formula-subsets","kind":"formula","src":"formula:subsets","title":"How many subsets","body":"subsets of n things = 2ⁿ. Each thing is in or out: every new thing doubles the ways.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"How many subsets: A set of 3 things: {a, b, c}.","opts":["8","9","7"],"after":"2 × 2 × 2 = 8 · { }, {a}, {b}, {c}, {a,b}, {a,c}, {b,c}, {a,b,c}: 8"},"level":10},"formula-why-subsets-0":{"id":"formula-why-subsets-0","kind":"formula-why","src":"formula:subsets#why0","title":"Why subsets of n things = 2ⁿ","body":"To make a subset, go through the things one at a time and decide: in, or out? Each thing doubles the number of ways, because every choice so far can go either way for the next thing.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-subsets-1":{"id":"formula-why-subsets-1","kind":"formula-why","src":"formula:subsets#why1","title":"Why subsets of n things = 2ⁿ","body":"With n things that is 2 × 2 × … × 2, n times: 2ⁿ. The count includes the empty set (everything out) and the whole set (everything in).","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-subsets":{"id":"formula-story-subsets","kind":"formula-story","src":"formula:subsets#story","badge":{"id":"story","label":"A story"},"title":"Pizza toppings","body":"Nova’s pizza has 4 toppings to choose from. You can have any of them, all of them, or none. How many different pizzas is that? — with Ines and Nova.","art":"art/s-kitchen.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-subsets":{"id":"formula-try-subsets","kind":"formula-try","src":"formula:subsets#gen0","title":"How many subsets — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A set has 6 things in it. How many subsets does it have, counting the empty set and the whole set?","opts":["64","65","63"],"after":"subsets of n things = 2ⁿ"},"level":10},"formula-percent-change":{"id":"formula-percent-change","kind":"formula","src":"formula:percent-change","title":"Percentage change","body":"% change = change ÷ original × 100. Compare the change with where it started.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Percentage change: A price goes from £50 to £60.","opts":["20","21","19"],"after":"change: 60 − 50 = 10 · 10 ÷ 50 × 100 = 20%"},"level":10},"formula-why-percent-change-0":{"id":"formula-why-percent-change-0","kind":"formula-why","src":"formula:percent-change#why0","title":"Why % change = change ÷ original × 100","body":"A rise of 10 means a lot on a price of 20 and very little on a price of 1,000. So we compare the change with where it started: change ÷ original.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-percent-change-1":{"id":"formula-why-percent-change-1","kind":"formula-why","src":"formula:percent-change#why1","title":"Why % change = change ÷ original × 100","body":"That gives a fraction of the original; multiply by 100 to say it as a percentage. Always divide by the ORIGINAL amount, never the new one — the change is measured from the start.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-percent-change":{"id":"formula-story-percent-change","kind":"formula-story","src":"formula:percent-change#story","badge":{"id":"story","label":"A story"},"title":"The sunflower","body":"Rafi’s sunflower was 80 cm tall last week. Today it is 100 cm. By what percentage did it grow? — with Ines and Rafi.","art":"art/s-garden.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-percent-change":{"id":"formula-try-percent-change","kind":"formula-try","src":"formula:percent-change#gen0","title":"Percentage change — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A price goes from £500 to £475. What is the percentage fall?","opts":["5","6","4"],"after":"% change = change ÷ original × 100"},"level":10},"formula-combinations":{"id":"formula-combinations","kind":"formula","src":"formula:combinations","title":"Permutations and combinations","body":"ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!). In order, one team of 3 is counted 3! = 6 times. Divide by 3! to count teams.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Permutations and combinations: A team of 3 from 7 players.","opts":["35","36","34"],"after":"in order: 7 × 6 × 5 = 210 · each team is counted 3! = 6 times · 210 ÷ 6 = 35"},"level":10},"formula-why-combinations-0":{"id":"formula-why-combinations-0","kind":"formula-why","src":"formula:combinations#why0","title":"Why ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!)","body":"When order matters — gold, silver, bronze — fill the places one at a time: n choices, then n − 1, for r places. That is ⁿPᵣ = n × (n − 1) × … (r numbers), which is n! with the tail (n − r)! cancelled off.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-why-combinations-1":{"id":"formula-why-combinations-1","kind":"formula-why","src":"formula:combinations#why1","title":"Why ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!)","body":"When order does not matter — a team, a handful of toppings — every group of r was counted once for each of its r! orders. So divide: ⁿCᵣ = ⁿPᵣ ÷ r!. A team of 3 from 7 is 7 × 6 × 5 = 210 in order, and 210 ÷ 6 = 35 teams.","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-story-combinations":{"id":"formula-story-combinations","kind":"formula-story","src":"formula:combinations#story","badge":{"id":"story","label":"A story"},"title":"Cone or cup?","body":"The ice-cream shop has 5 flavours. Theo wants 2 different scoops stacked on a cone; Ines wants 2 in a cup. — with Ines and Theo.","art":"art/s-shop.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":10},"formula-try-combinations":{"id":"formula-try-combinations","kind":"formula-try","src":"formula:combinations#gen0","title":"Permutations and combinations — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"6 in the final. How many ways to choose gold, silver and bronze?","opts":["120","121","119"],"after":"ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!)"},"level":10}};
